import React, { useEffect } from 'react';
import { HeaderMenu } from '../HeaderMenu';
import { SoundToggleButton } from '../SoundToggleButton';
import { TapHintButton } from '../TapHintButton';
import { useLoading } from '@/contexts/LoadingContext';
import { useAnimations } from '@/contexts/AnimationsContext';

interface MainPanelProps {
  id: string;
  onOpenSkins?: () => void;
}

export const MainPanel: React.FC<MainPanelProps> = ({ onOpenSkins }) => {
  const { isStarted } = useLoading();
  const {
    cookieRef,
    hasPlayedEntryAnimation,
    handleCookieClick,
    isUIHidden,
    isExplosionPlaying,
    resetExplosionState,
    triggerExplosion,
    playEntryAnimation,
  } = useAnimations();

  useEffect(() => {
    if (!isStarted || !cookieRef.current) return;

    if (!hasPlayedEntryAnimation) {
      // Запускаем entry анимацию через секунду после нажатия на кнопку "Начать"
      playEntryAnimation();
    } else {
      // При повторном заходе на MainPanel сбрасываем состояние взрыва и запускаем cycle
      resetExplosionState();
    }
  }, [isStarted, hasPlayedEntryAnimation, cookieRef, resetExplosionState, playEntryAnimation]);

  return (
    <div className="relative h-screen">
      <HeaderMenu
        isExplosionPlaying={isExplosionPlaying}
        onClose={resetExplosionState}
        onReload={triggerExplosion}
        onSkins={onOpenSkins}
        style={{
          transform: isUIHidden ? 'translateY(-100vh)' : 'translateY(0)',
        }}
      />
      <SoundToggleButton
        isHintHidden={isExplosionPlaying}
        style={{
          transform: isUIHidden ? 'translateY(100vh)' : 'translateY(0)',
        }}
      />
      {!isExplosionPlaying && (
        <TapHintButton
          onClick={handleCookieClick}
          style={{
            transform: isUIHidden ? 'translateY(100vh)' : 'translateY(0)',
          }}
        />
      )}
    </div>
  );
};
