import React, { useEffect, useState, useRef, useCallback } from 'react';
import type { Player } from '@/types/api';
import { api } from '@/services/api';
import TopIcon from '@/assets/icons/top.svg?react';
import { SPACING, TAB_MENU_HEIGHT } from '@/constants/ui';

interface LeaderboardPanelProps {
  id: string;
}

export const LeaderboardPanel: React.FC<LeaderboardPanelProps> = () => {
  const [players, setPlayers] = useState<Player[]>([]);
  const [currentUser, setCurrentUser] = useState<Player | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [hasMore, setHasMore] = useState(true);
  const [offset, setOffset] = useState(0);
  const scrollRef = useRef<HTMLDivElement>(null);
  const isLoadingMore = useRef(false);

  const loadLeaderboard = useCallback(async (currentOffset: number, append: boolean = false) => {
    if (isLoadingMore.current) return;

    try {
      isLoadingMore.current = true;
      const response = await api.getLeaderboard(currentOffset);

      setPlayers((prev) => (append ? [...prev, ...response.players] : response.players));
      setCurrentUser(response.currentUser);
      setHasMore(response.hasMore);
      setOffset(response.nextOffset);
    } catch (error) {
      console.error('Failed to load leaderboard:', error);
    } finally {
      setIsLoading(false);
      isLoadingMore.current = false;
    }
  }, []);

  useEffect(() => {
    loadLeaderboard(0);
  }, [loadLeaderboard]);

  const handleScroll = useCallback(() => {
    if (!scrollRef.current || !hasMore || isLoadingMore.current) return;

    const { scrollTop, scrollHeight, clientHeight } = scrollRef.current;

    // Загружаем больше когда пользователь близок к концу списка (осталось 100px)
    if (scrollHeight - scrollTop - clientHeight < 100) {
      loadLeaderboard(offset, true);
    }
  }, [hasMore, offset, loadLeaderboard]);

  if (isLoading) {
    return (
      <div className="flex h-screen items-center justify-center">
        <div
          className="h-16 w-16 animate-spin rounded-full border-[6px] border-solid border-primary"
          style={{
            borderTopColor: 'transparent',
          }}
        />
      </div>
    );
  }

  const getUserName = (user: Player) => {
    if (user.firstName && user.lastName) {
      return `${user.firstName} ${user.lastName}`;
    }
    return user.firstName || user.lastName || `Пользователь ${user.vkUserId}`;
  };

  const getUserPhoto = (user: Player) => {
    return user.photoUrl || 'https://placehold.co/36x36/1B354D/FEC14E?text=user';
  };

  return (
    <div
      className="relative flex h-screen flex-col"
      style={{
        paddingTop: `${SPACING * 2}px`,
      }}
    >
      {/* Fixed header section */}
      <div
        className="flex flex-col items-center gap-[20px]"
        style={{ paddingLeft: `${SPACING}px`, paddingRight: `${SPACING}px` }}
      >
        <div className="mx-auto flex flex-row justify-center gap-[10px]">
          <TopIcon className="w-[32px]" />
          <h1 className="font-nickname text-outline-3 text-center text-[32px] text-white">
            топ игроков
          </h1>
        </div>
        <div className="bg-secondary flex h-[50px] w-[200px] items-center justify-center rounded-[27px] px-[28px] text-center text-[16px] font-bold">
          <span className="translate-y-[2px]">Топ по открытым печенькам</span>
        </div>

        {/* Текущий игрок - всегда первый, выделен синим */}
        {currentUser && (
          <div className="bg-primary flex w-full items-center gap-[10px] rounded-[20px] px-[15px] py-[18px]">
            {/* Аватар */}
            <img
              src={getUserPhoto(currentUser)}
              alt="avatar"
              className="h-9 w-9 rounded-full"
            />

            {/* Информация об игроке */}
            <div className="flex flex-col gap-[5px]">
              <span className="font-eurostile text-[16px] text-white">
                {getUserName(currentUser)}
              </span>
              <span className="font-eurostile text-secondary text-[14px] font-bold">
                Открыто печенек: {currentUser.totalCookiesOpened}
              </span>
            </div>

            {/* Место в рейтинге */}
            <div className="ml-auto flex flex-col items-center">
              <span className="font-eurostile text-[14px] text-white">{currentUser.rank}</span>
              <span className="font-eurostile text-secondary text-[14px] font-bold">место</span>
            </div>
          </div>
        )}
      </div>

      {/* Scrollable list of top players */}
      <div
        ref={scrollRef}
        onScroll={handleScroll}
        className="overflow-y-auto pt-[20px]"
        style={{
          paddingBottom: `${TAB_MENU_HEIGHT + SPACING}px`,
          paddingLeft: `${SPACING}px`,
          paddingRight: `${SPACING}px`,
        }}
      >
        <div className="flex flex-col gap-[10px]">
          {/* Топ игроков */}
          {players
            .filter((player) => !currentUser || player.vkUserId !== currentUser.vkUserId)
            .map((player) => {
              const isTopThree = player.rank <= 3;
              const isTopFive = player.rank <= 5;

              return (
                <div
                  key={player.vkUserId}
                  className="flex items-center gap-[10px] rounded-[20px] bg-white px-[15px] py-[18px]"
                >
                {/* Аватар */}
                <img
                  src={getUserPhoto(player)}
                  alt={`${getUserName(player)} avatar`}
                  className="h-9 w-9 rounded-full"
                />

                {/* Информация об игроке */}
                <div className="flex flex-col gap-[5px]">
                  <span className="font-eurostile text-primary text-[16px]">
                    {getUserName(player)}
                  </span>
                  <span className="font-eurostile text-primary text-[14px] font-bold">
                    Открыто печенек: {player.totalCookiesOpened}
                  </span>
                </div>

                {/* Номер места */}
                <div
                  className="font-eurostile text-primary ml-auto flex h-9 w-9 items-center justify-center rounded-full text-[24px] font-bold"
                  style={{
                    backgroundColor: isTopThree
                      ? 'var(--color-secondary)'
                      : isTopFive
                        ? '#E4E4E4'
                        : 'transparent',
                  }}
                >
                  <span className="mt-[7px]">{player.rank}</span>
                </div>
              </div>
            );
          })}

          {/* Индикатор загрузки при скролле */}
          {hasMore && !isLoading && (
            <div className="flex justify-center py-6">
              <div
                className="h-8 w-8 animate-spin rounded-full border-[4px] border-solid border-primary"
                style={{
                  borderTopColor: 'transparent',
                }}
              />
            </div>
          )}
        </div>
      </div>
    </div>
  );
};
