import React, { createContext, useContext, useState, useCallback } from 'react';
import { FullscreenSpinner } from '@/components/FullscreenSpinner';

interface GlobalSpinnerContextValue {
  showSpinner: () => void;
  hideSpinner: () => void;
  isVisible: boolean;
}

const GlobalSpinnerContext = createContext<GlobalSpinnerContextValue | null>(null);

export const GlobalSpinnerProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isVisible, setIsVisible] = useState(false);

  const showSpinner = useCallback(() => {
    setIsVisible(true);
  }, []);

  const hideSpinner = useCallback(() => {
    setIsVisible(false);
  }, []);

  return (
    <GlobalSpinnerContext.Provider value={{ showSpinner, hideSpinner, isVisible }}>
      {children}
      <FullscreenSpinner visible={isVisible} />
    </GlobalSpinnerContext.Provider>
  );
};

export const useGlobalSpinner = () => {
  const context = useContext(GlobalSpinnerContext);
  if (!context) {
    throw new Error('useGlobalSpinner must be used within GlobalSpinnerProvider');
  }
  return context;
};
