import React, { createContext, useContext, useState, useCallback } from 'react';
import type { ModalConfig } from '@/types/modal';
import { Modal } from '@/components/Modal';
import { MODAL_CLEANUP_DELAY } from '@/constants/animations';

interface ModalContextType {
  showModal: (config: ModalConfig) => void;
  hideModal: () => void;
}

const ModalContext = createContext<ModalContextType | undefined>(undefined);

export const ModalProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [modalConfig, setModalConfig] = useState<ModalConfig | null>(null);
  const [isOpen, setIsOpen] = useState(false);

  const showModal = useCallback((config: ModalConfig) => {
    setModalConfig(config);
    setIsOpen(true);
  }, []);

  const hideModal = useCallback(() => {
    setIsOpen(false);
    setTimeout(() => {
      setModalConfig(null);
    }, MODAL_CLEANUP_DELAY);
  }, []);

  return (
    <ModalContext.Provider value={{ showModal, hideModal }}>
      {children}
      {modalConfig && (
        <Modal
          isOpen={isOpen}
          onClose={hideModal}
          icon={modalConfig.icon}
          title={modalConfig.title}
          description={modalConfig.description}
          buttonText={modalConfig.buttonText}
          reward={modalConfig.reward}
          onButtonClick={modalConfig.onButtonClick}
          secondaryButtonText={modalConfig.secondaryButtonText}
          onSecondaryButtonClick={modalConfig.onSecondaryButtonClick}
        />
      )}
    </ModalContext.Provider>
  );
};

export const useModal = () => {
  const context = useContext(ModalContext);
  if (context === undefined) {
    throw new Error('useModal must be used within a ModalProvider');
  }
  return context;
};
