import React, { createContext, useContext, useState, useCallback } from 'react';

interface LoadingState {
  video: boolean;
  cookieAnimation: boolean;
  audio: boolean;
  initialRender: boolean;
  userData: boolean; // Данные пользователя загружены
  lastFortune: boolean; // Последнее предсказание загружено
  fonts: boolean; // Шрифты для сторис загружены
}

interface LoadingContextValue {
  loadingState: LoadingState;
  setResourceLoaded: (resource: keyof LoadingState) => void;
  isAllLoaded: boolean;
  isStarted: boolean;
  setIsStarted: (started: boolean) => void;
}

const LoadingContext = createContext<LoadingContextValue | null>(null);

export const LoadingProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [loadingState, setLoadingState] = useState<LoadingState>({
    video: false,
    cookieAnimation: false,
    audio: false,
    initialRender: true,
    userData: false,
    lastFortune: false,
    fonts: false,
  });
  const [isStarted, setIsStarted] = useState<boolean>(false);

  const setResourceLoaded = useCallback((resource: keyof LoadingState) => {
    setLoadingState((prev) => ({
      ...prev,
      [resource]: true,
    }));
  }, []);

  const isAllLoaded = Object.values(loadingState).every((loaded) => loaded);

  return (
    <LoadingContext.Provider
      value={{
        loadingState,
        setResourceLoaded,
        isAllLoaded,
        isStarted,
        setIsStarted,
      }}
    >
      {children}
    </LoadingContext.Provider>
  );
};

export const useLoading = () => {
  const context = useContext(LoadingContext);
  if (!context) {
    throw new Error('useLoading must be used within LoadingProvider');
  }
  return context;
};
