import bridge from '@vkontakte/vk-bridge';
import type { Fortune } from '@/types/api';
import type { CookieSkin } from '@/components/FloatingCookie';
import { generateStoryImage } from './storyImageGenerator';
import { isVKMobileApp } from '@/utils/platform';

const VK_GROUP_ID = Number(import.meta.env.VITE_VK_GROUP_ID);
const VK_APP_ID = Number(import.meta.env.VITE_VK_APP_ID);

/** Методы VK Bridge, используемые в тасках */
export type VKTaskMethod =
  | 'VKWebAppJoinGroup'
  | 'VKWebAppAllowMessagesFromGroup'
  | 'VKWebAppAllowNotifications'
  | 'VKWebAppAddToHomeScreen'
  | 'VKWebAppShowStoryBox';

/**
 * Методы, которые работают только в мобильном приложении VK (не в браузере)
 */
const MOBILE_APP_ONLY_METHODS: VKTaskMethod[] = [
  'VKWebAppAddToHomeScreen',
  'VKWebAppAllowNotifications',
];

/**
 * Проверяет, поддерживается ли метод VK Bridge на текущей платформе.
 * Комбинирует supportsAsync + проверку платформы для методов с ограничениями.
 */
export async function isVKMethodSupported(method: VKTaskMethod): Promise<boolean> {
  // Сначала проверяем, существует ли метод в API
  const apiSupported = await bridge.supportsAsync(method);
  if (!apiSupported) {
    return false;
  }

  // Дополнительная проверка платформы для методов с ограничениями
  if (MOBILE_APP_ONLY_METHODS.includes(method)) {
    return isVKMobileApp();
  }

  return true;
}

export const vkTasks = {
  /**
   * Subscribe to VK group
   */
  async subscribeToGroup(): Promise<boolean> {
    try {
      const result = await bridge.send('VKWebAppJoinGroup', {
        group_id: VK_GROUP_ID,
      });
      return result.result === true;
    } catch (error) {
      console.error('Failed to join group:', error);
      return false;
    }
  },

  /**
   * Allow messages from community
   */
  async allowMessages(): Promise<boolean> {
    try {
      const result = await bridge.send('VKWebAppAllowMessagesFromGroup', {
        group_id: VK_GROUP_ID,
      });
      // VK Bridge может вернуть result в разных форматах
      // На мобильных: { result: true } или просто успешный ответ без ошибки
      const success = result.result === true || (result && !('error' in result));
      return success;
    } catch (error: unknown) {
      // Проверяем, не отменил ли пользователь действие
      const vkError = error as { error_type?: string; error_data?: { error_code?: number; error_reason?: string } };
      console.error('VKWebAppAllowMessagesFromGroup error:', JSON.stringify(vkError, null, 2));
      return false;
    }
  },

  /**
   * Allow notifications from app
   */
  async allowNotifications(): Promise<boolean> {
    try {
      const result = await bridge.send('VKWebAppAllowNotifications');
      return result.result === true;
    } catch (error) {
      console.error('Failed to allow notifications:', error);
      return false;
    }
  },

  /**
   * Add app to home screen
   */
  async addToHomeScreen(): Promise<boolean> {
    try {
      const result = await bridge.send('VKWebAppAddToHomeScreen');
      return result.result === true;
    } catch (error) {
      console.error('Failed to add to home screen:', error);
      return false;
    }
  },

  /**
   * Share fortune to story with skin-specific background
   */
  async shareToStory(fortune: Fortune, skin: CookieSkin): Promise<boolean> {
    try {
      // Generate story image with text on background (returns data:image/jpeg;base64,...)
      const imageDataUrl = await generateStoryImage({
        text: fortune.text,
        skin,
      });

      // VK Bridge accepts full data URL with prefix
      const result = await bridge.send('VKWebAppShowStoryBox', {
        background_type: 'image',
        blob: imageDataUrl,
        attachment: {
          text: 'open',
          type: 'url',
          url: `https://vk.com/app${VK_APP_ID}`,
        },
      });
      return result.result === true;
    } catch (error) {
      console.error('Failed to share to story:', error);
      return false;
    }
  },
};
