/* eslint-disable react-hooks/set-state-in-effect */
import React, { useEffect, useLayoutEffect, useState } from 'react';
import type { SnackbarConfig } from '@/types/snackbar';
import { SPACING } from '@/constants/ui';

interface SnackbarProps extends SnackbarConfig {
  isOpen: boolean;
  onClose: () => void;
}

export const Snackbar: React.FC<SnackbarProps> = ({
  isOpen,
  onClose,
  icon,
  title,
  description,
  duration = 3000,
}) => {
  const [isClosing, setIsClosing] = useState(false);
  const [shouldRender, setShouldRender] = useState(isOpen);

  // Handle opening and closing animations using useLayoutEffect for synchronous DOM updates
  useLayoutEffect(() => {
    if (isOpen) {
      setShouldRender(true);
      setIsClosing(false);
    } else if (shouldRender) {
      setIsClosing(true);
      const timer = setTimeout(() => {
        setShouldRender(false);
        setIsClosing(false);
      }, 300); // Match animation duration
      return () => clearTimeout(timer);
    }
  }, [isOpen, shouldRender]);

  // Auto-close after duration
  useEffect(() => {
    if (isOpen && duration > 0) {
      const timer = setTimeout(() => {
        onClose();
      }, duration);
      return () => clearTimeout(timer);
    }
  }, [isOpen, duration, onClose]);

  if (!shouldRender) return null;

  const contentClass = isClosing ? 'snackbar-exit' : 'snackbar-enter';

  return (
    <div
      className={`${contentClass} fixed z-[2] flex items-center gap-[12px] rounded-[12px] bg-white px-[10px] py-[12px]`}
      style={{
        left: `${SPACING}px`,
        right: `${SPACING}px`,
        top: `${SPACING}px`,
      }}
    >
      {icon && <div className="flex-shrink-0">{icon}</div>}
      <div className="flex min-w-0 flex-1 flex-col justify-center gap-[4px]">
        <h3 className="font-eurostile text-primary text-[16px] font-bold">{title}</h3>
        {description && <p className="text-primary text-[14px] font-medium">{description}</p>}
      </div>
    </div>
  );
};
