import type { CookieSkin } from '@/components/FloatingCookie';

// Story dimensions (VK standard)
const STORY_WIDTH = 1080;
const STORY_HEIGHT = 1920;

// Text styles matching FortuneText component
const TEXT_COLOR = '#49382E';
const TEXT_WIDTH_RATIO = 0.55; // 55vw equivalent

// Import story backgrounds
import standartBg from '@/assets/images/storyBackgrounds/standart.jpg';
import roseBg from '@/assets/images/storyBackgrounds/rose.jpg';
import tieBg from '@/assets/images/storyBackgrounds/tie.jpg';
import lipsBg from '@/assets/images/storyBackgrounds/lips.jpg';
import fuckmanBg from '@/assets/images/storyBackgrounds/fuckman.jpg';
import glassesBg from '@/assets/images/storyBackgrounds/glasses.jpg';

// Import font
import nicknameFont from '@/assets/fonts/nickname.ttf';

// Map skins to backgrounds
const SKIN_BACKGROUNDS: Record<CookieSkin, string> = {
  standart2: standartBg,
  rose: roseBg,
  tie: tieBg,
  lips: lipsBg,
  fuckman: fuckmanBg,
  glasses: glassesBg,
};

// Load font once
let fontLoaded = false;
let fontLoadPromise: Promise<void> | null = null;

/**
 * Preload the Nickname font for story generation.
 * Should be called early (e.g., during app loading) to avoid font issues on iOS.
 */
export async function preloadStoryFont(): Promise<void> {
  if (fontLoaded) return;

  // Reuse existing promise if already loading
  if (fontLoadPromise) return fontLoadPromise;

  fontLoadPromise = (async () => {
    const font = new FontFace('Nickname', `url(${nicknameFont})`);
    await font.load();
    document.fonts.add(font);
    fontLoaded = true;
  })();

  return fontLoadPromise;
}

async function loadNicknameFont(): Promise<void> {
  return preloadStoryFont();
}

// Load image from URL
function loadImage(src: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = src;
  });
}

// Wrap text to fit within maxWidth
function wrapText(ctx: CanvasRenderingContext2D, text: string, maxWidth: number): string[] {
  const words = text.split(' ');
  const lines: string[] = [];
  let currentLine = '';

  for (const word of words) {
    const testLine = currentLine ? `${currentLine} ${word}` : word;
    const metrics = ctx.measureText(testLine);

    if (metrics.width > maxWidth && currentLine) {
      lines.push(currentLine);
      currentLine = word;
    } else {
      currentLine = testLine;
    }
  }

  if (currentLine) {
    lines.push(currentLine);
  }

  return lines;
}

export interface GenerateStoryImageOptions {
  text: string;
  skin: CookieSkin;
}

/**
 * Generates a story image with fortune text on skin-specific background
 * @returns Base64 data URL of the generated image
 */
export async function generateStoryImage({
  text,
  skin,
}: GenerateStoryImageOptions): Promise<string> {
  // Ensure font is loaded
  await loadNicknameFont();

  // Create canvas
  const canvas = document.createElement('canvas');
  canvas.width = STORY_WIDTH;
  canvas.height = STORY_HEIGHT;
  const ctx = canvas.getContext('2d');

  if (!ctx) {
    throw new Error('Failed to get canvas context');
  }

  // Load and draw background
  const backgroundUrl = SKIN_BACKGROUNDS[skin];
  const background = await loadImage(backgroundUrl);
  ctx.drawImage(background, 0, 0, STORY_WIDTH, STORY_HEIGHT);

  const fontSize = 54;
  ctx.font = `normal ${fontSize}px Nickname`;
  ctx.fillStyle = TEXT_COLOR;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  // Calculate text area
  const maxTextWidth = STORY_WIDTH * TEXT_WIDTH_RATIO;

  // Wrap text
  const lines = wrapText(ctx, text, maxTextWidth);

  // Calculate line height (100% leading = fontSize)
  const lineHeight = fontSize;

  // Position text in center
  const textY = STORY_HEIGHT * 0.445;
  const totalTextHeight = lines.length * lineHeight;
  const startY = textY - totalTextHeight / 2 + lineHeight / 2;

  // Draw each line
  lines.forEach((line, index) => {
    const y = startY + index * lineHeight;
    ctx.fillText(line, STORY_WIDTH / 2, y);
  });

  // Convert to base64
  return canvas.toDataURL('image/jpeg', 0.9);
}
