import { useCallback, useRef } from 'react';
import { useUser } from '@/contexts/UserContext';
import { useFortune } from '@/contexts/FortuneContext';
import { useAudio } from '@/contexts/AudioContext';
import { useModal } from '@/contexts/ModalContext';
import { useNavigation } from '@/contexts/NavigationContext';
import { useMetrics } from '@/contexts/MetricsContext';
import { TabId } from '@/types/navigation';
import type { FloatingCookieRef } from '@/components/FloatingCookie';
import type { FortuneTextRef } from '@/components/FortuneText';
import {
  CLICKS_TO_EXPLOSION,
  FORTUNE_TEXT_DELAY,
  UI_RETURN_DELAY,
  CLICK_RESET_TIMEOUT,
} from '@/constants/animations';
import { COOKIE_COST } from '@/constants/game';

interface UseCookieClickHandlerProps {
  cookieRef: React.RefObject<FloatingCookieRef | null>;
  fortuneTextRef: React.RefObject<FortuneTextRef | null>;
  isExplosionPlaying: boolean;
  isEntryAnimationPlaying: boolean;
  hasPlayedEntryAnimation: boolean;
  setIsExplosionPlaying: (playing: boolean) => void;
  setIsUIHidden: (hidden: boolean) => void;
  hideTimeoutRef: React.MutableRefObject<NodeJS.Timeout | null>;
  clearClicksTimeoutRef: React.MutableRefObject<NodeJS.Timeout | null>;
  hasOpenedCookieRef: React.MutableRefObject<boolean>;
}

export const useCookieClickHandler = ({
  cookieRef,
  fortuneTextRef,
  isExplosionPlaying,
  isEntryAnimationPlaying,
  hasPlayedEntryAnimation,
  setIsExplosionPlaying,
  setIsUIHidden,
  hideTimeoutRef,
  clearClicksTimeoutRef,
  hasOpenedCookieRef,
}: UseCookieClickHandlerProps) => {
  const { openCookie, userData } = useUser();
  const { setCurrentFortune, setLastFortune, lastFortune } = useFortune();
  const { playCookieClick, playCookieExplosive } = useAudio();
  const { showModal } = useModal();
  const { navigateToTab } = useNavigation();
  const { trackCookieView, trackOpenNextCookie } = useMetrics();
  const clickCountRef = useRef<number>(0);

  const balance = userData?.balance ?? 0;

  const handleCookieClick = useCallback(() => {
    // Блокируем клики во время взрыва, entry анимации или если entry анимация вообще не проигрывалась
    if (isExplosionPlaying || isEntryAnimationPlaying || !hasPlayedEntryAnimation) {
      return;
    }

    // Проверяем баланс перед любыми действиями
    if (balance < COOKIE_COST) {
      // Показываем модалку с предложением перейти к заданиям
      showModal({
        title: 'Упс, недостаточно печенек для предсказания',
        description: 'Выполняйте задания, чтобы заработать больше печенек!',
        buttonText: 'К заданиям',
        onButtonClick: () => {
          navigateToTab(TabId.TASKS);
        },
      });
      return;
    }

    if (cookieRef.current) {
      playCookieClick();

      // Увеличиваем счетчик кликов
      clickCountRef.current += 1;

      // Скрываем UI
      setIsUIHidden(true);

      // Проверяем, достигли ли нужного количества кликов для взрыва
      if (clickCountRef.current >= CLICKS_TO_EXPLOSION) {
        // Устанавливаем флаг воспроизведения взрыва
        // После взрыва анимация останавливается на последнем кадре
        // и клики остаются заблокированными навсегда
        setIsExplosionPlaying(true);

        // Устанавливаем флаг что юзер открыл печеньку
        hasOpenedCookieRef.current = true;

        // Запускаем анимацию и звук взрыва
        playCookieExplosive();
        cookieRef.current.playExplosive();
        clickCountRef.current = 0;

        // Очищаем таймер сброса кликов
        if (clearClicksTimeoutRef.current) {
          clearTimeout(clearClicksTimeoutRef.current);
        }

        // Трекаем событие open_next_cookie (перед открытием новой печеньки)
        trackOpenNextCookie(lastFortune?._id ?? null);

        // Открываем печенье на бэкенде и показываем текст предсказания после завершения взрыва
        setTimeout(async () => {
          if (fortuneTextRef.current) {
            try {
              const response = await openCookie();
              if (response) {
                setCurrentFortune(response.fortune);
                setLastFortune(response.fortune); // Обновляем lastFortune для кнопки reload
                fortuneTextRef.current.show(response.fortune.text);
                // Трекаем событие cookie_view (после показа предсказания)
                trackCookieView(response.fortune._id);
              }
            } catch (error) {
              // Обрабатываем ошибки (кроме недостаточного баланса, так как он проверяется заранее)
              console.error('Error opening cookie:', error);
              fortuneTextRef.current.show('Что-то пошло не так...');
            }
          }
        }, FORTUNE_TEXT_DELAY);

        // Возвращаем UI (но НЕ hint кнопку!)
        if (hideTimeoutRef.current) {
          clearTimeout(hideTimeoutRef.current);
        }
        hideTimeoutRef.current = setTimeout(() => {
          setIsUIHidden(false);
        }, UI_RETURN_DELAY);
      } else {
        // Обычный клик
        cookieRef.current.playClick();

        // Очищаем предыдущий таймер скрытия UI
        if (hideTimeoutRef.current) {
          clearTimeout(hideTimeoutRef.current);
        }

        // Очищаем предыдущий таймер сброса кликов
        if (clearClicksTimeoutRef.current) {
          clearTimeout(clearClicksTimeoutRef.current);
        }

        // Возвращаем UI
        hideTimeoutRef.current = setTimeout(() => {
          setIsUIHidden(false);
        }, UI_RETURN_DELAY);

        // Сбрасываем счетчик кликов после периода неактивности
        clearClicksTimeoutRef.current = setTimeout(() => {
          clickCountRef.current = 0;
        }, CLICK_RESET_TIMEOUT);
      }
    }
  }, [
    playCookieClick,
    playCookieExplosive,
    isExplosionPlaying,
    isEntryAnimationPlaying,
    hasPlayedEntryAnimation,
    openCookie,
    setCurrentFortune,
    setLastFortune,
    lastFortune,
    showModal,
    navigateToTab,
    balance,
    cookieRef,
    fortuneTextRef,
    setIsExplosionPlaying,
    setIsUIHidden,
    hideTimeoutRef,
    clearClicksTimeoutRef,
    hasOpenedCookieRef,
    trackCookieView,
    trackOpenNextCookie,
  ]);

  return handleCookieClick;
};
