import React, { createContext, useContext, useState, useCallback, useRef } from 'react';
import type { CookieSkin } from '@/components/FloatingCookie';
import { useGlobalSpinner } from './GlobalSpinnerContext';

interface SkinsContextValue {
  currentSkin: CookieSkin;
  isSkinsOpen: boolean;
  openSkins: () => void;
  closeSkins: () => void;
  selectSkin: (skin: CookieSkin, onLoaded?: () => void) => void;
  triggerSkinLoadedCallback: () => void;
}

const SkinsContext = createContext<SkinsContextValue | null>(null);

export const SkinsProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentSkin, setCurrentSkin] = useState<CookieSkin>('standart2');
  const [isSkinsOpen, setIsSkinsOpen] = useState<boolean>(false);
  const onSkinLoadedCallbackRef = useRef<(() => void) | null>(null);
  const { showSpinner, hideSpinner } = useGlobalSpinner();

  const openSkins = useCallback(() => {
    setIsSkinsOpen(true);
  }, []);

  const closeSkins = useCallback(() => {
    setIsSkinsOpen(false);
  }, []);

  const selectSkin = useCallback(
    (skin: CookieSkin, onLoaded?: () => void) => {
      setCurrentSkin(skin);
      showSpinner();
      if (onLoaded) {
        onSkinLoadedCallbackRef.current = onLoaded;
      }
    },
    [showSpinner]
  );

  const triggerSkinLoadedCallback = useCallback(() => {
    hideSpinner();
    if (onSkinLoadedCallbackRef.current) {
      onSkinLoadedCallbackRef.current();
      onSkinLoadedCallbackRef.current = null;
    }
  }, [hideSpinner]);

  return (
    <SkinsContext.Provider
      value={{
        currentSkin,
        isSkinsOpen,
        openSkins,
        closeSkins,
        selectSkin,
        triggerSkinLoadedCallback,
      }}
    >
      {children}
    </SkinsContext.Provider>
  );
};

export const useSkins = () => {
  const context = useContext(SkinsContext);
  if (!context) {
    throw new Error('useSkins must be used within SkinsProvider');
  }
  return context;
};
