import React, { useState } from 'react';
import { SKINS } from '@/constants/skins';
import type { CookieSkin } from '@/components/FloatingCookie';
import { SkinsPanelHeader } from '../SkinsPanelHeader';
import ChevronIcon from '@/assets/icons/chevron.svg?react';
import DoneIcon from '@/assets/icons/done.svg?react';
import { SPACING, TAB_MENU_HEIGHT } from '@/constants/ui';

interface SkinsPanelProps {
  id: string;
  currentSkin: CookieSkin;
  onSkinSelect: (skin: CookieSkin, onLoaded: () => void) => void;
  onClose?: () => void;
}

export const SkinsPanel: React.FC<SkinsPanelProps> = ({ currentSkin, onSkinSelect, onClose }) => {
  const [currentIndex, setCurrentIndex] = useState(() => {
    const index = SKINS.findIndex((s) => s.id === currentSkin);
    return index >= 0 ? index : 0;
  });
  const [isLoading, setIsLoading] = useState(false);

  const skin = SKINS[currentIndex];
  const isSkinSelected = skin.id === currentSkin;

  const handlePrevious = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
    }
  };

  const handleNext = () => {
    if (currentIndex < SKINS.length - 1) {
      setCurrentIndex(currentIndex + 1);
    }
  };

  const handleSelect = () => {
    if (!isSkinSelected && !isLoading) {
      setIsLoading(true);
      onSkinSelect(skin.id, () => {
        setIsLoading(false);
      });
    }
  };

  const SkinIcon = skin.icon;

  return (
    <div
      className="relative h-screen"
      style={{
        paddingBottom: `${TAB_MENU_HEIGHT + SPACING}px`,
      }}
    >
      <SkinsPanelHeader onClose={onClose} />

      <div className="relative flex h-full flex-col items-center justify-center">
        <SkinIcon className="ml-auto h-auto w-[85%] object-contain" />

        <span className="text-outline-2 font-eurostile text-secondary mt-[4.5%] text-[24px] font-bold">
          Категория:
        </span>

        <div className="mt-[1.5%] flex h-[47px] items-center justify-center gap-[15px]">
          <button
            className="cursor-pointer"
            style={{
              opacity: currentIndex === 0 ? 0.5 : 1,
              pointerEvents: currentIndex === 0 ? 'none' : 'auto',
            }}
            onClick={handlePrevious}
          >
            <ChevronIcon className="text-secondary h-full w-full" />
          </button>

          <span className="text-outline-4 font-nickname w-[194px] text-center text-[36px] text-white">
            {skin.name}
          </span>

          <button
            className="rotate-180 cursor-pointer"
            style={{
              opacity: currentIndex === SKINS.length - 1 ? 0.5 : 1,
              pointerEvents: currentIndex === SKINS.length - 1 ? 'none' : 'auto',
            }}
            onClick={handleNext}
          >
            <ChevronIcon className="text-secondary h-full w-full" />
          </button>
        </div>

        <button
          className="font-eurostile mt-[7.5%] flex h-[50px] w-[200px] cursor-pointer items-center justify-center gap-[5px] rounded-[40px] text-[20px] font-bold disabled:opacity-70"
          style={{
            backgroundColor: isSkinSelected ? 'var(--color-primary)' : 'var(--color-secondary)',
            color: isSkinSelected ? 'var(--color-secondary)' : 'var(--color-primary)',
          }}
          onClick={handleSelect}
          disabled={isLoading}
        >
          {isLoading ? (
            <div
              className="h-5 w-5 animate-spin rounded-full border-3 border-solid"
              style={{
                borderColor: isSkinSelected ? 'var(--color-secondary)' : 'var(--color-primary)',
                borderTopColor: 'transparent',
              }}
            />
          ) : (
            <>
              {isSkinSelected && <DoneIcon />}
              <span className="translate-y-[2px]">{isSkinSelected ? 'Выбрано' : 'Выбрать'}</span>
            </>
          )}
        </button>
      </div>
    </div>
  );
};
