import React, { useEffect } from 'react';
import { AdaptivityProvider, ConfigProvider } from '@vkontakte/vkui';
import bridge from '@vkontakte/vk-bridge';

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || 'http://localhost:3001/api';

interface VKProviderProps {
  children: React.ReactNode;
}

export const VKProvider: React.FC<VKProviderProps> = ({ children }) => {
  useEffect(() => {
    const initVK = async () => {
      try {
        // Инициализация VK Bridge
        await bridge.send('VKWebAppInit');

        // Получаем launch параметры
        const launchParams = await bridge.send('VKWebAppGetLaunchParams');

        // Получаем информацию о пользователе
        const userInfo = await bridge.send('VKWebAppGetUserInfo');

        // Формируем строку параметров для backend
        const vkParamsArray: Array<[string, string]> = [];
        Object.entries(launchParams).forEach(([key, value]) => {
          if (key.startsWith('vk_') || key === 'sign') {
            vkParamsArray.push([key, String(value)]);
          }
        });

        // Формируем строку без двойного кодирования
        const paramsString = vkParamsArray
          .map(([key, value]) => `${key}=${value}`)
          .join('&');

        // Отправляем данные на backend для авторизации
        const response = await fetch(`${API_BASE_URL}/users/login`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'x-vk-launch-params': paramsString,
          },
          body: JSON.stringify({
            firstName: userInfo.first_name,
            lastName: userInfo.last_name,
            photoUrl: userInfo.photo_200 || userInfo.photo_100,
          }),
        });

        if (!response.ok) {
          const errorText = await response.text();
          console.error('Login failed:', errorText);
          throw new Error(`Login failed: ${errorText}`);
        }
      } catch (error) {
        console.error('VK initialization error:', error);
        // Ошибка будет обработана в UserContext при загрузке данных
      }
    };

    initVK();
  }, []);

  return (
    <ConfigProvider>
      <AdaptivityProvider>{children}</AdaptivityProvider>
    </ConfigProvider>
  );
};
