import bridge from '@vkontakte/vk-bridge';
import type { UserData, OpenCookieResponse, LeaderboardResponse, Fortune, CompleteTaskResponse, TasksStatusResponse, TrackEventDto } from '@/types/api';

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || 'http://localhost:3001/api';

class ApiService {
  private async getAuthHeaders(): Promise<HeadersInit> {
    try {
      // Получаем launch params от VK Bridge
      const launchParams = await bridge.send('VKWebAppGetLaunchParams');

      // Формируем строку параметров для backend (так же как в VKProvider)
      const vkParamsArray: Array<[string, string]> = [];
      Object.entries(launchParams).forEach(([key, value]) => {
        if (key.startsWith('vk_') || key === 'sign') {
          vkParamsArray.push([key, String(value)]);
        }
      });

      const paramsString = vkParamsArray.map(([key, value]) => `${key}=${value}`).join('&');

      return {
        'Content-Type': 'application/json',
        'x-vk-launch-params': paramsString,
      };
    } catch (error) {
      console.error('Failed to get VK auth params:', error);
      return {
        'Content-Type': 'application/json',
      };
    }
  }

  private async request<T>(endpoint: string, options?: RequestInit): Promise<T> {
    const headers = await this.getAuthHeaders();

    const response = await fetch(`${API_BASE_URL}${endpoint}`, {
      ...options,
      headers: {
        ...headers,
        ...options?.headers,
      },
    });

    if (!response.ok) {
      const error = await response.json().catch(() => ({ message: response.statusText }));
      throw new Error(error.message || 'API request failed');
    }

    // Handle 204 No Content responses
    if (response.status === 204) {
      return undefined as T;
    }

    return response.json();
  }

  // Ежедневный логин (получение баланса и награды)
  async processDailyLogin(): Promise<UserData> {
    return this.request<UserData>('/users/login', {
      method: 'POST',
    });
  }

  // Открыть печенье
  async openCookie(): Promise<OpenCookieResponse> {
    return this.request<OpenCookieResponse>('/fortunes/open', {
      method: 'POST',
    });
  }

  // Получить последнее предсказание пользователя
  async getLastFortune(): Promise<Fortune> {
    return this.request<Fortune>('/fortunes/last');
  }

  // Получить таблицу лидеров
  async getLeaderboard(offset: number = 0): Promise<LeaderboardResponse> {
    return this.request<LeaderboardResponse>(`/leaderboard?offset=${offset}`);
  }

  // Завершить таск
  async completeTask(taskId: string): Promise<CompleteTaskResponse> {
    return this.request<CompleteTaskResponse>(`/tasks/${taskId}/complete`, {
      method: 'POST',
    });
  }

  // Получить статус всех тасков
  async getTasksStatus(): Promise<TasksStatusResponse> {
    return this.request<TasksStatusResponse>('/tasks/status');
  }

  // Отправить событие метрики
  async trackEvent(event: TrackEventDto): Promise<void> {
    await this.request<void>('/metrics/track', {
      method: 'POST',
      body: JSON.stringify(event),
    });
  }

}

export const api = new ApiService();