import React, { createContext, useContext, useRef, useEffect, useState, useCallback } from 'react';
import { useLoading } from './LoadingContext';
import { isVKMobileApp } from '@/utils/platform';

interface AudioContextValue {
  playBackgroundCookie: () => void;
  playBackgroundNoCookie: () => void;
  playCookieClick: () => void;
  playCookieExplosive: () => void;
  playTextTyping: () => void;
  stopAll: () => void;
  mute: (muted: boolean) => void;
  toggleMute: () => void;
  isMuted: boolean;
}

interface AudioProviderProps {
  children: React.ReactNode;
}

const AudioContext = createContext<AudioContextValue | null>(null);

export const AudioProvider: React.FC<AudioProviderProps> = ({ children }) => {
  const { setResourceLoaded, loadingState } = useLoading();
  const webAudioContextRef = useRef<globalThis.AudioContext | null>(null);
  const gainNodeRef = useRef<GainNode | null>(null);
  const backgroundCookieNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const backgroundNoCookieNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const audioBuffersRef = useRef<{ [key: string]: AudioBuffer }>({});
  const [isInitialized, setIsInitialized] = useState(false);
  const [isMuted, setIsMuted] = useState(true); // По умолчанию звук выключен

  // Сохраняем текущий трек для восстановления после iOS interrupt
  const currentBackgroundTrackRef = useRef<'background_cookie' | 'background_no_cookie' | null>(
    null
  );
  // Ref для функции playBackground чтобы избежать циклической зависимости в useEffect
  const playBackgroundRef = useRef<
    ((audioName: 'background_cookie' | 'background_no_cookie') => void) | null
  >(null);

  // Приостанавливаем аудио когда приложение сворачивают
  // На iOS visibilitychange может не срабатывать, поэтому используем несколько событий
  useEffect(() => {
    // Восстанавливаем аудио при возврате в приложение
    const handleResume = () => {
      if (!webAudioContextRef.current || isMuted) return;

      // На iOS AudioContext может быть в состоянии 'interrupted', нужен resume()
      webAudioContextRef.current.resume().then(() => {
        // На iOS после resume() AudioBufferSourceNode может быть в невалидном состоянии
        // Проверяем и перезапускаем фоновую музыку если нужно
        const ctx = webAudioContextRef.current;
        if (ctx && ctx.state === 'running' && currentBackgroundTrackRef.current) {
          // Проверяем, что текущий источник ещё активен
          const currentSource =
            currentBackgroundTrackRef.current === 'background_cookie'
              ? backgroundCookieNodeRef.current
              : backgroundNoCookieNodeRef.current;

          // Если источника нет или он завершился, перезапускаем
          if (!currentSource) {
            // Используем setTimeout чтобы избежать race condition с React state
            setTimeout(() => {
              if (currentBackgroundTrackRef.current && playBackgroundRef.current) {
                playBackgroundRef.current(currentBackgroundTrackRef.current);
              }
            }, 100);
          }
        }
      });
    };

    // Приостанавливаем аудио при сворачивании
    const handlePause = () => {
      if (webAudioContextRef.current) {
        webAudioContextRef.current.suspend();
      }
    };

    const handleVisibilityChange = () => {
      if (document.hidden) {
        handlePause();
      } else {
        handleResume();
      }
    };

    // pageshow срабатывает при возврате из bfcache и при переключении на вкладку в iOS
    const handlePageShow = (event: PageTransitionEvent) => {
      // persisted означает что страница была восстановлена из bfcache
      if (event.persisted || !document.hidden) {
        handleResume();
      }
    };

    // focus/blur только для мобильных приложений VK, где visibilitychange ненадёжен
    const handleFocus = () => handleResume();
    const handleBlur = () => handlePause();
    const isMobile = isVKMobileApp();

    document.addEventListener('visibilitychange', handleVisibilityChange);
    window.addEventListener('pageshow', handlePageShow);
    if (isMobile) {
      window.addEventListener('focus', handleFocus);
      window.addEventListener('blur', handleBlur);
    }

    return () => {
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      window.removeEventListener('pageshow', handlePageShow);
      if (isMobile) {
        window.removeEventListener('focus', handleFocus);
        window.removeEventListener('blur', handleBlur);
      }
    };
  }, [isMuted]);

  useEffect(() => {
    // Загружаем аудио только после первого рендера (LoadingScreen показан)
    if (!loadingState.initialRender) return;

    const initAudio = async () => {
      // Создаём Web Audio API контекст
      // Поддержка старых браузеров (Safari) и префиксов webkit
      const AudioContextConstructor =
        window.AudioContext ||
        (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;

      const ctx = new AudioContextConstructor();
      webAudioContextRef.current = ctx;

      // Создаём GainNode для управления громкостью
      const gainNode = ctx.createGain();
      gainNode.connect(ctx.destination);
      gainNode.gain.value = 0; // По умолчанию выключено
      gainNodeRef.current = gainNode;

      // Загружаем аудио файлы асинхронно
      try {
        // Используем import.meta.url для правильных путей в production
        const audioFiles = {
          background_cookie: new URL('../assets/audio/background_cookie.mp3', import.meta.url).href,
          background_no_cookie: new URL('../assets/audio/background_no_cookie.mp3', import.meta.url)
            .href,
          cookie_click: new URL('../assets/audio/cookie_click.mp3', import.meta.url).href,
          cookie_explosive: new URL('../assets/audio/cookie_explosive.mp3', import.meta.url).href,
          text_typing: new URL('../assets/audio/text_typing.mp3', import.meta.url).href,
        };

        for (const [audioName, audioUrl] of Object.entries(audioFiles)) {
          const response = await fetch(audioUrl);
          const arrayBuffer = await response.arrayBuffer();
          const audioBuffer = await ctx.decodeAudioData(arrayBuffer);
          audioBuffersRef.current[audioName] = audioBuffer;
        }

        setIsInitialized(true);

        // Уведомляем LoadingContext о завершении загрузки аудио
        setResourceLoaded('audio');
      } catch (error) {
        console.error('Failed to load audio files:', error);
        // Всё равно отмечаем как загруженное, чтобы не блокировать UI
        setResourceLoaded('audio');
      }
    };

    initAudio();

    return () => {
      if (backgroundCookieNodeRef.current) {
        try {
          backgroundCookieNodeRef.current.stop();
        } catch {
          // Ignore stop errors - source already stopped
        }
        backgroundCookieNodeRef.current = null;
      }
      if (backgroundNoCookieNodeRef.current) {
        try {
          backgroundNoCookieNodeRef.current.stop();
        } catch {
          // Ignore stop errors - source already stopped
        }
        backgroundNoCookieNodeRef.current = null;
      }
      if (webAudioContextRef.current) {
        webAudioContextRef.current.close();
        webAudioContextRef.current = null;
      }
    };
  }, [setResourceLoaded, loadingState.initialRender]);

  const createAudioSource = useCallback(
    (audioName: string): AudioBufferSourceNode | null => {
      if (!isInitialized || !webAudioContextRef.current || !gainNodeRef.current) return null;

      // Возобновляем AudioContext если он был приостановлен (требование браузеров)
      if (webAudioContextRef.current.state === 'suspended') {
        webAudioContextRef.current.resume();
      }

      const audioBuffer = audioBuffersRef.current[audioName];
      if (!audioBuffer) return null;

      const source = webAudioContextRef.current.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(gainNodeRef.current);

      if (audioName.includes('background')) {
        source.loop = true;
      }

      return source;
    },
    [isInitialized]
  );

  const playBackground = useCallback(
    (audioName: 'background_cookie' | 'background_no_cookie') => {
      if (!isInitialized) return;

      const targetRef =
        audioName === 'background_cookie' ? backgroundCookieNodeRef : backgroundNoCookieNodeRef;
      const otherRef =
        audioName === 'background_cookie' ? backgroundNoCookieNodeRef : backgroundCookieNodeRef;

      // Останавливаем другую фоновую музыку
      if (otherRef.current) {
        try {
          otherRef.current.stop();
        } catch {
          // Ignore stop errors - source already stopped
        }
        otherRef.current = null;
      }

      // Останавливаем текущую если играет
      if (targetRef.current) {
        try {
          targetRef.current.stop();
        } catch {
          // Ignore stop errors - source already stopped
        }
      }

      // Сохраняем текущий трек для восстановления после iOS interrupt
      currentBackgroundTrackRef.current = audioName;

      // Создаём и запускаем новый источник
      const source = createAudioSource(audioName);
      if (source) {
        targetRef.current = source;
        source.start(0);
      }
    },
    [isInitialized, createAudioSource]
  );

  // Обновляем ref для использования в visibility change handler
  useEffect(() => {
    playBackgroundRef.current = playBackground;
  }, [playBackground]);

  const playBackgroundCookie = useCallback(() => {
    playBackground('background_cookie');
  }, [playBackground]);

  const playBackgroundNoCookie = useCallback(() => {
    playBackground('background_no_cookie');
  }, [playBackground]);

  const playCookieClick = useCallback(() => {
    if (!isInitialized) return;

    // Создаём и запускаем звук клика (без сохранения в ref, т.к. короткий звук)
    const source = createAudioSource('cookie_click');
    if (source) {
      source.start(0);
    }
  }, [isInitialized, createAudioSource]);

  const playCookieExplosive = useCallback(() => {
    if (!isInitialized) return;

    // Создаём и запускаем звук взрыва (без сохранения в ref, т.к. короткий звук)
    const source = createAudioSource('cookie_explosive');
    if (source) {
      source.start(0);
    }
  }, [isInitialized, createAudioSource]);

  const playTextTyping = useCallback(() => {
    if (!isInitialized) return;

    // Создаём и запускаем звук печатания
    const source = createAudioSource('text_typing');
    if (source) {
      source.start(0);
    }
  }, [isInitialized, createAudioSource]);

  const stopAll = useCallback(() => {
    if (backgroundCookieNodeRef.current) {
      try {
        backgroundCookieNodeRef.current.stop();
      } catch {
        // Ignore stop errors - already stopped
      }
      backgroundCookieNodeRef.current = null;
    }
    if (backgroundNoCookieNodeRef.current) {
      try {
        backgroundNoCookieNodeRef.current.stop();
      } catch {
        // Ignore stop errors - already stopped
      }
      backgroundNoCookieNodeRef.current = null;
    }
  }, []);

  const mute = useCallback((muted: boolean) => {
    if (gainNodeRef.current) {
      gainNodeRef.current.gain.value = muted ? 0 : 1;
      setIsMuted(muted);
    }
  }, []);

  const toggleMute = useCallback(() => {
    mute(!isMuted);
  }, [isMuted, mute]);

  return (
    <AudioContext.Provider
      value={{
        playBackgroundCookie,
        playBackgroundNoCookie,
        playCookieClick,
        playCookieExplosive,
        playTextTyping,
        stopAll,
        mute,
        toggleMute,
        isMuted,
      }}
    >
      {children}
    </AudioContext.Provider>
  );
};

export const useAudio = () => {
  const context = useContext(AudioContext);
  if (!context) {
    throw new Error('useAudio must be used within AudioProvider');
  }
  return context;
};
