import React from 'react';
import CookieIcon from '@/assets/icons/cookie.svg?react';
import SkinsIcon from '@/assets/icons/skins.svg?react';
import ReloadIcon from '@/assets/icons/reload.svg?react';
import CloseIcon from '@/assets/icons/close.svg?react';
import { SPACING } from '@/constants/ui';
import { useUser } from '@/contexts/UserContext';
import { isVKMobile } from '@/utils/platform';

interface HeaderMenuProps {
  style?: React.CSSProperties;
  isExplosionPlaying?: boolean;
  onClose?: () => void;
  onReload?: () => void;
  onSkins?: () => void;
}

export const HeaderMenu: React.FC<HeaderMenuProps> = ({
  style,
  isExplosionPlaying = false,
  onClose,
  onReload,
  onSkins,
}) => {
  const { userData } = useUser();
  const balance = userData?.balance ?? 0;
  const lastFortuneId = userData?.lastFortuneId ?? null;

  return (
    <div
      className="fixed top-0 right-0 left-0 z-2 flex justify-between px-[20px]"
      style={{
        paddingTop: isVKMobile() ? `${SPACING * 3}px` : `${SPACING}px`,
        paddingBottom: `${SPACING}px`,
        transition: 'transform 400ms ease-in-out',
        ...style,
      }}
    >
      <div className="bg-primary flex rounded-[15px] p-[10px]">
        <div className="flex items-center gap-[5px]">
          <CookieIcon />
          <span className="font-nickname text-[24px] text-white">{balance}</span>
        </div>
      </div>
      <div className="flex gap-[5px]">
        {isExplosionPlaying ? (
          <button
            className="bg-primary flex h-[50px] w-[50px] cursor-pointer items-center justify-center rounded-[15px]"
            onClick={onClose}
          >
            <CloseIcon className="text-secondary" />
          </button>
        ) : (
          <>
            {lastFortuneId && (
              <button
                className="bg-primary flex h-[50px] w-[50px] cursor-pointer items-center justify-center rounded-[15px]"
                onClick={onReload}
              >
                <ReloadIcon />
              </button>
            )}
            <button
              className="bg-primary flex h-[50px] w-[50px] cursor-pointer items-center justify-center rounded-[15px]"
              onClick={onSkins}
            >
              <SkinsIcon />
            </button>
          </>
        )}
      </div>
    </div>
  );
};
