import React, { createContext, useContext, useState, useRef, useCallback, useEffect } from 'react';
import type { FloatingCookieRef } from '@/components/FloatingCookie';
import type { FortuneTextRef } from '@/components/FortuneText';
import { useAudio } from './AudioContext';
import { useModal } from './ModalContext';
import { useFortune } from './FortuneContext';
import { useSkins } from './SkinsContext';
import { useCookieClickHandler } from '@/hooks/useCookieClickHandler';
import { vkTasks } from '@/services/vkTasks';
import { FORTUNE_TEXT_DELAY, UI_RETURN_DELAY } from '@/constants/animations';

interface AnimationsContextValue {
  cookieRef: React.RefObject<FloatingCookieRef | null>;
  fortuneTextRef: React.RefObject<FortuneTextRef | null>;
  hasPlayedEntryAnimation: boolean;
  setHasPlayedEntryAnimation: (played: boolean) => void;
  handleCookieClick: () => void;
  isUIHidden: boolean;
  isExplosionPlaying: boolean;
  resetExplosionState: () => void;
  triggerExplosion: () => void;
  hasOpenedCookie: boolean;
  playEntryAnimation: () => Promise<void>;
}

const AnimationsContext = createContext<AnimationsContextValue | null>(null);

export const AnimationsProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [hasPlayedEntryAnimation, setHasPlayedEntryAnimation] = useState<boolean>(false);
  const [isUIHidden, setIsUIHidden] = useState<boolean>(false);
  const [isExplosionPlaying, setIsExplosionPlaying] = useState<boolean>(false);
  const [isEntryAnimationPlaying, setIsEntryAnimationPlaying] = useState<boolean>(false);
  const cookieRef = useRef<FloatingCookieRef>(null);
  const fortuneTextRef = useRef<FortuneTextRef>(null);
  const hideTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const clearClicksTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const hasShownShareModalRef = useRef<boolean>(false); // Флаг что модалка шаринга уже показывалась
  const hasOpenedCookieRef = useRef<boolean>(false); // Флаг что юзер хотя бы раз открыл печеньку
  const { playCookieExplosive } = useAudio();
  const { showModal } = useModal();
  const { lastFortune } = useFortune();
  const { currentSkin } = useSkins();

  // Используем хук для обработки кликов по печеньке
  const handleCookieClick = useCookieClickHandler({
    cookieRef,
    fortuneTextRef,
    isExplosionPlaying,
    isEntryAnimationPlaying,
    hasPlayedEntryAnimation,
    setIsExplosionPlaying,
    setIsUIHidden,
    hideTimeoutRef,
    clearClicksTimeoutRef,
    hasOpenedCookieRef,
  });

  // Сброс состояния взрыва и запуск cycle анимации
  const resetExplosionState = useCallback(() => {
    setIsExplosionPlaying(false);

    // Скрываем текст предсказания
    if (fortuneTextRef.current) {
      fortuneTextRef.current.hide();
    }

    // Запускаем cycle анимацию
    if (cookieRef.current) {
      cookieRef.current.playCycle();
    }

    // Показываем модалку с предложением поделиться только один раз после первого открытия печеньки
    if (!hasShownShareModalRef.current && hasOpenedCookieRef.current) {
      hasShownShareModalRef.current = true;

      showModal({
        title: 'Эта печенька может порадовать кого-то ещё',
        description: 'Если захочется – поделись!',
        buttonText: 'Поделиться',
        onButtonClick: async () => {
          if (lastFortune) {
            await vkTasks.shareToStory(lastFortune, currentSkin);
          }
        },
        secondaryButtonText: 'Не сейчас',
      });
    }
  }, [showModal]);

  // Прямой вызов explosion анимации (для кнопки Reload)
  const triggerExplosion = useCallback(() => {
    // Если взрыв уже играет, ничего не делаем
    if (isExplosionPlaying) {
      return;
    }

    if (cookieRef.current && fortuneTextRef.current) {
      // Скрываем UI
      setIsUIHidden(true);

      // Устанавливаем флаг воспроизведения взрыва
      setIsExplosionPlaying(true);

      // Запускаем анимацию и звук взрыва
      playCookieExplosive();
      cookieRef.current.playExplosive();

      // Очищаем таймер сброса кликов
      if (clearClicksTimeoutRef.current) {
        clearTimeout(clearClicksTimeoutRef.current);
      }

      // Показываем предзагруженное последнее предсказание после завершения взрыва
      setTimeout(() => {
        if (fortuneTextRef.current) {
          if (lastFortune) {
            fortuneTextRef.current.show(lastFortune.text);
          } else {
            fortuneTextRef.current.show('Откройте печеньку, чтобы получить предсказание!');
          }
        }
      }, FORTUNE_TEXT_DELAY);

      // Возвращаем UI (но НЕ hint кнопку!)
      if (hideTimeoutRef.current) {
        clearTimeout(hideTimeoutRef.current);
      }
      hideTimeoutRef.current = setTimeout(() => {
        setIsUIHidden(false);
      }, UI_RETURN_DELAY);
    }
  }, [playCookieExplosive, isExplosionPlaying, lastFortune]);

  // Метод для воспроизведения entry анимации (используется при смене скина)
  const playEntryAnimation = useCallback(async () => {
    if (!cookieRef.current) return;

    setIsEntryAnimationPlaying(true);

    try {
      await cookieRef.current.playEntry();
      setHasPlayedEntryAnimation(true);
    } finally {
      setIsEntryAnimationPlaying(false);
    }
  }, []);

  // Очищаем таймеры при размонтировании
  useEffect(() => {
    return () => {
      if (hideTimeoutRef.current) {
        clearTimeout(hideTimeoutRef.current);
      }
      if (clearClicksTimeoutRef.current) {
        clearTimeout(clearClicksTimeoutRef.current);
      }
    };
  }, []);

  return (
    <AnimationsContext.Provider
      value={{
        cookieRef,
        fortuneTextRef,
        hasPlayedEntryAnimation,
        setHasPlayedEntryAnimation,
        handleCookieClick,
        isUIHidden,
        isExplosionPlaying,
        resetExplosionState,
        triggerExplosion,
        hasOpenedCookie: hasOpenedCookieRef.current,
        playEntryAnimation,
      }}
    >
      {children}
    </AnimationsContext.Provider>
  );
};

export const useAnimations = () => {
  const context = useContext(AnimationsContext);
  if (!context) {
    throw new Error('useAnimations must be used within AnimationsProvider');
  }
  return context;
};
