import React from 'react';
import type { Task } from '@/types/tasks';
import GoIcon from '@/assets/icons/go.svg?react';
import DoneIcon from '@/assets/icons/done.svg?react';

interface TaskItemProps {
  task: Task;
  icon?: React.ReactNode;
  completed?: boolean;
}

export const TaskItem: React.FC<TaskItemProps> = ({ task, icon, completed = false }) => {
  const handleClick = () => {
    if (!completed && task.onClick) {
      task.onClick();
    }
  };

  return (
    <div
      className={`flex items-center gap-[10px] rounded-[20px] bg-white px-[15px] py-[16px] transition-transform ${
        completed ? 'opacity-80' : 'cursor-pointer active:scale-[0.98]'
      }`}
      onClick={handleClick}
    >
      {icon && <div className="h-9 w-9 flex-shrink-0">{icon}</div>}
      <div className="flex min-w-0 flex-1 items-center gap-[5px]">
        <span className="font-eurostile text-primary translate-y-[4px] text-[18px] font-bold">
          {task.title}
        </span>
      </div>
      <div className="ml-auto h-5 w-5 flex-shrink-0">
        {completed ? (
          <DoneIcon className="h-full w-full" />
        ) : (
          <GoIcon className="h-full w-full text-[#658FB6]" />
        )}
      </div>
    </div>
  );
};
