/* eslint-disable react-hooks/set-state-in-effect */
import React, { useEffect, useLayoutEffect, useState } from 'react';
import type { ModalConfig } from '@/types/modal';
import CloseIcon from '@/assets/icons/close.svg?react';
import CookieIcon from '@/assets/icons/cookie.svg?react';

interface ModalProps extends ModalConfig {
  isOpen: boolean;
  onClose: () => void;
}

export const Modal: React.FC<ModalProps> = ({
  isOpen,
  onClose,
  icon,
  title,
  description,
  buttonText,
  reward,
  onButtonClick,
  secondaryButtonText,
  onSecondaryButtonClick,
}) => {
  const [isClosing, setIsClosing] = useState(false);
  const [shouldRender, setShouldRender] = useState(isOpen);

  // Handle opening and closing animations using useLayoutEffect for synchronous DOM updates
  useLayoutEffect(() => {
    if (isOpen) {
      setShouldRender(true);
      setIsClosing(false);
    } else if (shouldRender) {
      setIsClosing(true);
      const timer = setTimeout(() => {
        setShouldRender(false);
        setIsClosing(false);
      }, 300); // Match animation duration
      return () => clearTimeout(timer);
    }
  }, [isOpen, shouldRender]);

  // Block body scroll when modal is open
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }

    return () => {
      document.body.style.overflow = '';
    };
  }, [isOpen]);

  if (!shouldRender) return null;

  const handleButtonClick = () => {
    if (onButtonClick) {
      onButtonClick();
    }
    onClose();
  };

  const handleSecondaryButtonClick = () => {
    if (onSecondaryButtonClick) {
      onSecondaryButtonClick();
    }
    onClose();
  };

  const handleBackdropClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (e.target === e.currentTarget) {
      onClose();
    }
  };

  const backdropClass = isClosing ? 'modal-backdrop-exit' : 'modal-backdrop-enter';
  const contentClass = isClosing ? 'modal-content-exit' : 'modal-content-enter';

  return (
    <div
      className={`${backdropClass} fixed inset-0 z-2 flex items-end justify-center bg-[#0D1B2999] px-[20px]`}
      onClick={handleBackdropClick}
      role="dialog"
      aria-modal="true"
      aria-labelledby="modal-title"
      aria-describedby="modal-description"
    >
      <div
        className={`${contentClass} bg-primary relative mb-[20px] flex w-full flex-col items-center gap-[20px] rounded-[20px] px-[20px] py-[30px]`}
      >
        {!secondaryButtonText && (
          <button
            onClick={onClose}
            className="absolute top-[20px] right-[20px] justify-center transition-transform active:scale-[0.9]"
            aria-label="Закрыть"
          >
            <CloseIcon className="h-[27px] w-[27px] text-[#13283A]" />
          </button>
        )}
        {icon && <div className="h-20 w-20">{icon}</div>}
        <h2
          id="modal-title"
          className={`font-eurostile text-center text-[24px] leading-[110%] font-bold text-white ${!secondaryButtonText && !icon ? 'mt-[30px]' : ''}`}
        >
          {title}
        </h2>
        <p
          id="modal-description"
          className="text-left text-[14px] font-medium whitespace-pre-line text-[#BBCEDF]"
        >
          {description}
        </p>
        <div className="flex w-full flex-col gap-[12px]">
          <button
            onClick={handleButtonClick}
            className="bg-secondary font-eurostile text-primary flex w-full items-center justify-center rounded-[40px] py-[17px] text-[20px] font-bold transition-transform active:scale-[0.98]"
          >
            <span className="translate-y-[2px]">{buttonText}</span>
          </button>
          {secondaryButtonText && (
            <button
              onClick={handleSecondaryButtonClick}
              className="font-eurostile text-primary flex w-full items-center justify-center rounded-[40px] bg-white py-[17px] text-[20px] font-bold transition-transform active:scale-[0.98]"
            >
              <span className="translate-y-[2px]">{secondaryButtonText}</span>
            </button>
          )}
        </div>
        {reward !== undefined && (
          <div className="font-nickname flex items-center gap-[7px] text-[36px] text-white">
            + <CookieIcon /> {reward}
          </div>
        )}
      </div>
    </div>
  );
};
