import React, { useEffect, useCallback, useRef } from 'react';
import { TabMenu } from '@/components/TabMenu';
import { LoadingScreen } from '@/components/LoadingScreen';
import FloatingCookie, { type CookieSkin } from '@/components/FloatingCookie';
import { FortuneText } from '@/components/FortuneText';
import { useLoading } from '@/contexts/LoadingContext';
import { useAnimations } from '@/contexts/AnimationsContext';
import { useAudio } from '@/contexts/AudioContext';
import { useSkins } from '@/contexts/SkinsContext';
import { useSnackbar } from '@/contexts/SnackbarContext';
import { useUser } from '@/contexts/UserContext';
import { useMetrics } from '@/contexts/MetricsContext';
import { TabId, type TabItem } from '@/types/navigation';
import { SKIN_CHANGE_ANIMATION_DELAY, VIDEO_PLAYBACK_RATES } from '@/constants/animations';
import { preloadStoryFont } from '@/services/storyImageGenerator';
import backgroundVideo from '@/assets/video/background_cycle.mp4';
import SnackbarCookieIcon from '@/assets/icons/snackbar_cookie.svg?react';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: TabId;
  onTabChange: (tabId: TabId) => void;
  tabs: TabItem[];
  currentSkin: CookieSkin;
}

const LayoutContent: React.FC<LayoutProps> = ({
  children,
  activeTab,
  onTabChange,
  tabs,
  currentSkin,
}) => {
  const { setResourceLoaded, isAllLoaded, isStarted, setIsStarted } = useLoading();
  const { cookieRef, fortuneTextRef, handleCookieClick, isUIHidden, playEntryAnimation } =
    useAnimations();
  const { mute } = useAudio();
  const { triggerSkinLoadedCallback } = useSkins();
  const { showSnackbar } = useSnackbar();
  const { userData } = useUser();
  const { trackAppOpen } = useMetrics();
  const isNewDay = userData?.isNewDay ?? false;
  const videoRef = useRef<HTMLVideoElement>(null);
  const isInitialLoadRef = useRef(true);

  const handleVideoLoaded = () => {
    setResourceLoaded('video');
  };

  // Предзагрузка шрифтов для сторис (особенно важно для iOS)
  useEffect(() => {
    preloadStoryFont()
      .then(() => setResourceLoaded('fonts'))
      .catch(() => setResourceLoaded('fonts')); // Загрузка UI не должна блокироваться ошибкой шрифтов
  }, [setResourceLoaded]);

  const handleStart = () => {
    setIsStarted(true);
    // Включаем звук после нажатия кнопки "Начать"
    mute(false);
    // Трекаем событие app_open
    trackAppOpen();

    // Показываем приветственный snackbar только если это новый день (первый визит за день)
    if (isNewDay) {
      showSnackbar({
        icon: <SnackbarCookieIcon />,
        title: 'Добро пожаловать!',
        description: (
          <>
            Здесь каждый день появляются <span className="font-bold">3 печеньки</span>. Возвращайся,
            когда захочется.
          </>
        ),
        duration: 5000,
      });
    }
  };

  const handleAnimationLoaded = useCallback(() => {
    setResourceLoaded('cookieAnimation');

    // Вызываем callback из SkinsPanel если он есть (это переключит нас на MAIN)
    triggerSkinLoadedCallback();

    // После смены скина (не первой загрузки) и если приложение уже запущено
    if (!isInitialLoadRef.current && isStarted && cookieRef.current) {
      // Запускаем entry анимацию после небольшой задержки, чтобы успел произойти переход на MAIN
      setTimeout(() => {
        playEntryAnimation();
      }, SKIN_CHANGE_ANIMATION_DELAY);
    }

    // После первой загрузки меняем флаг
    isInitialLoadRef.current = false;
  }, [setResourceLoaded, isStarted, cookieRef, triggerSkinLoadedCallback, playEntryAnimation]);

  // Управление скоростью видео в зависимости от активной панели
  useEffect(() => {
    if (!videoRef.current || !isStarted) return;

    const newSpeed =
      activeTab === TabId.MAIN
        ? VIDEO_PLAYBACK_RATES.MAIN_PANEL
        : VIDEO_PLAYBACK_RATES.OTHER_PANELS;
    videoRef.current.playbackRate = newSpeed;
  }, [activeTab, isStarted]);

  // Восстанавливаем воспроизведение видео при возврате в приложение (особенно важно для iOS)
  // На iOS visibilitychange может не срабатывать, поэтому используем несколько событий
  useEffect(() => {
    const resumeVideo = () => {
      if (!videoRef.current) return;
      const video = videoRef.current;
      if (video.paused) {
        video.play().catch(() => {
          // Если автоматический play не сработал, попробуем ещё раз
          setTimeout(() => {
            video.play().catch(() => {});
          }, 100);
        });
      }
    };

    const handleVisibilityChange = () => {
      if (!document.hidden) {
        resumeVideo();
      }
    };

    const handlePageShow = (event: PageTransitionEvent) => {
      if (event.persisted || !document.hidden) {
        resumeVideo();
      }
    };

    const handleFocus = () => resumeVideo();

    document.addEventListener('visibilitychange', handleVisibilityChange);
    window.addEventListener('pageshow', handlePageShow);
    window.addEventListener('focus', handleFocus);

    return () => {
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      window.removeEventListener('pageshow', handlePageShow);
      window.removeEventListener('focus', handleFocus);
    };
  }, []);

  return (
    <div className="relative h-screen w-full overflow-hidden">
      {/* Фоновое видео */}
      <video
        ref={videoRef}
        className="fixed top-0 left-0 h-full w-full object-cover"
        src={backgroundVideo}
        autoPlay
        loop
        muted
        playsInline
        onLoadedData={handleVideoLoaded}
      />

      {!isStarted && <LoadingScreen isAllLoaded={isAllLoaded} onStart={handleStart} />}

      <div
        className="relative h-full overflow-y-auto"
        style={{ opacity: isAllLoaded && isStarted ? 1 : 0 }}
      >
        {children}
      </div>

      {/* FloatingCookie живёт на уровне Layout и не размонтируется */}
      <FloatingCookie
        ref={cookieRef}
        skin={currentSkin}
        onAnimationLoaded={handleAnimationLoaded}
        onClick={handleCookieClick}
      />

      {/* Fortune text для предсказаний */}
      <FortuneText ref={fortuneTextRef} />

      {isStarted && (
        <div
          className="transition-transform duration-[400ms] ease-in-out"
          style={{
            transform: isUIHidden ? 'translateY(100vh)' : 'translateY(0)',
          }}
        >
          <TabMenu activeTab={activeTab} onTabChange={onTabChange} tabs={tabs} />
        </div>
      )}

    </div>
  );
};

export const Layout: React.FC<LayoutProps> = (props) => {
  return <LayoutContent {...props} />;
};
