import React from 'react';
import { VKProvider } from '@/platforms/vk/VKProvider';
import { NavigationProvider } from '@/contexts/NavigationContext';
import { LoadingProvider } from '@/contexts/LoadingContext';
import { AudioProvider } from '@/contexts/AudioContext';
import { SnackbarProvider } from '@/contexts/SnackbarContext';
import { ModalProvider } from '@/contexts/ModalContext';
import { UserProvider } from '@/contexts/UserContext';
import { FortuneProvider } from '@/contexts/FortuneContext';
import { AnimationsProvider } from '@/contexts/AnimationsContext';
import { SkinsProvider } from '@/contexts/SkinsContext';
import { TasksProvider } from '@/contexts/TasksContext';
import { MetricsProvider } from '@/contexts/MetricsContext';
import { GlobalSpinnerProvider } from '@/contexts/GlobalSpinnerContext';

interface AppProvidersProps {
  children: React.ReactNode;
}

/**
 * Компонент-обёртка для всех Context провайдеров приложения.
 * Упрощает структуру App.tsx и делает дерево провайдеров более управляемым.
 */
export const AppProviders: React.FC<AppProvidersProps> = ({ children }) => {
  return (
    <VKProvider>
      <MetricsProvider>
        <NavigationProvider>
          <LoadingProvider>
            <AudioProvider>
              <SnackbarProvider>
                <ModalProvider>
                  <UserProvider>
                    <FortuneProvider>
                      <GlobalSpinnerProvider>
                        <SkinsProvider>
                          <AnimationsProvider>
                            <TasksProvider>{children}</TasksProvider>
                          </AnimationsProvider>
                        </SkinsProvider>
                      </GlobalSpinnerProvider>
                    </FortuneProvider>
                  </UserProvider>
                </ModalProvider>
              </SnackbarProvider>
            </AudioProvider>
          </LoadingProvider>
        </NavigationProvider>
      </MetricsProvider>
    </VKProvider>
  );
};
