import React from 'react';
import { TabId, type TabItem } from '@/types/navigation';
import { TAB_MENU_HEIGHT } from '@/constants/ui';

interface TabMenuProps {
  activeTab: TabId;
  onTabChange: (tabId: TabId) => void;
  tabs: TabItem[];
}

export const TabMenu: React.FC<TabMenuProps> = ({ activeTab, onTabChange, tabs }) => {
  return (
    <div
      className="bg-primary fixed right-0 bottom-0 left-0 z-[2] flex items-center rounded-t-[30px] pb-[10px]"
      style={{ height: `${TAB_MENU_HEIGHT}px` }}
    >
      <div
        className="grid w-full"
        style={{ gridTemplateColumns: `repeat(${tabs.length}, minmax(0, 1fr))` }}
      >
        {tabs.map((tab) => (
          <button
            key={tab.id}
            onClick={() => onTabChange(tab.id)}
            className={`flex cursor-pointer flex-col items-center justify-center gap-[5px] ${
              activeTab === tab.id ? 'text-white' : 'text-[#658FB6]'
            }`}
          >
            {tab.icon}
            <span className="font-regular text-[12px]">{tab.label}</span>
          </button>
        ))}
      </div>
    </div>
  );
};
