/**
 * VK Platform detection utilities
 * vk_platform values: mobile_android, mobile_iphone, mobile_web, desktop_web
 */

type VKPlatform = 'mobile_android' | 'mobile_iphone' | 'mobile_web' | 'desktop_web' | 'unknown';

let cachedPlatform: VKPlatform | null = null;

/**
 * Get VK platform from URL launch params (synchronous)
 */
export function getVKPlatform(): VKPlatform {
  if (cachedPlatform) return cachedPlatform;

  const urlParams = new URLSearchParams(window.location.search);
  const platform = urlParams.get('vk_platform') as VKPlatform | null;

  cachedPlatform = platform || 'unknown';
  return cachedPlatform;
}

/**
 * Check if running on VK mobile app (Android/iOS native apps)
 */
export function isVKMobileApp(): boolean {
  const platform = getVKPlatform();
  return platform === 'mobile_android' || platform === 'mobile_iphone';
}

/**
 * Check if running on any mobile platform (including mobile web)
 */
export function isVKMobile(): boolean {
  const platform = getVKPlatform();
  return platform === 'mobile_android' || platform === 'mobile_iphone' || platform === 'mobile_web';
}

/**
 * Check if running on desktop
 */
export function isVKDesktop(): boolean {
  const platform = getVKPlatform();
  return platform === 'desktop_web';
}
