import React, { useState, useEffect } from 'react';
import loadingScreenBg from '@/assets/images/loading-screen-bg.webp';
import CookieImage from '@/assets/images/cookie.svg?react';

interface LoadingScreenProps {
  isAllLoaded: boolean;
  onStart: () => void;
}

export const LoadingScreen: React.FC<LoadingScreenProps> = ({ isAllLoaded, onStart }) => {
  // const isAllLoaded = false;
  const [dots, setDots] = useState(0);

  useEffect(() => {
    // Анимация точек
    const dotsInterval = setInterval(() => {
      setDots((prev) => (prev >= 3 ? 0 : prev + 1));
    }, 500);

    return () => {
      clearInterval(dotsInterval);
    };
  }, []);

  return (
    <div
      className="fixed inset-0 z-1 flex flex-col items-center justify-end gap-[30px] pt-[7vh] pb-[16vh]"
      style={{
        backgroundImage: `url(${loadingScreenBg})`,
        backgroundSize: 'cover',
        backgroundPosition: 'center',
      }}
    >
      <div
        style={{
          marginLeft: 'auto',
          marginBottom: 'auto',
          width: '85%',
          display: 'flex',
          justifyContent: 'flex-end',
          alignItems: 'center',
        }}
      >
        <CookieImage style={{ width: '100%', height: 'auto' }} />
      </div>
      <div className="flex min-h-[150px] items-end">
        {isAllLoaded ? (
          <div className="flex flex-col items-center gap-[30px]">
            <button
              onClick={onStart}
              className="animate-button-bounce font-nickname bg-primary h-[72px] w-[80vw] rounded-[100px] text-[40px] leading-[52px] font-normal tracking-[-0.5px] text-white"
            >
              Начать
            </button>
          </div>
        ) : (
          <div className="flex flex-col items-center gap-[30px]">
            <svg width="80" height="80" className="svg-loading" viewBox="25 25 50 50">
              <circle className="svg-loading-path-background" cx="50" cy="50" r="20" />
              <circle className="svg-loading-path" cx="50" cy="50" r="20" />
            </svg>
            <h1 className="text-outline-4 font-nickname text-center text-[40px] leading-[52px] font-normal tracking-[-0.5px] text-white">
              Идёт <span className="text-secondary">загрузка{'.'.repeat(dots)}</span>
            </h1>
          </div>
        )}
      </div>
    </div>
  );
};
