import React, { createContext, useContext, useState, useCallback } from 'react';
import { Snackbar } from '@/components/Snackbar';
import type { SnackbarConfig } from '@/types/snackbar';
import { SNACKBAR_CLEANUP_DELAY } from '@/constants/animations';

interface SnackbarContextType {
  showSnackbar: (config: SnackbarConfig) => void;
  hideSnackbar: () => void;
}

const SnackbarContext = createContext<SnackbarContextType | undefined>(undefined);

export const SnackbarProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [snackbarConfig, setSnackbarConfig] = useState<SnackbarConfig | null>(null);
  const [isOpen, setIsOpen] = useState(false);

  const showSnackbar = useCallback((config: SnackbarConfig) => {
    setSnackbarConfig(config);
    setIsOpen(true);
  }, []);

  const hideSnackbar = useCallback(() => {
    setIsOpen(false);
    setTimeout(() => {
      setSnackbarConfig(null);
    }, SNACKBAR_CLEANUP_DELAY);
  }, []);

  return (
    <SnackbarContext.Provider value={{ showSnackbar, hideSnackbar }}>
      {children}
      {snackbarConfig && (
        <Snackbar
          isOpen={isOpen}
          onClose={hideSnackbar}
          icon={snackbarConfig.icon}
          title={snackbarConfig.title}
          description={snackbarConfig.description}
          duration={snackbarConfig.duration}
        />
      )}
    </SnackbarContext.Provider>
  );
};

export const useSnackbar = () => {
  const context = useContext(SnackbarContext);
  if (context === undefined) {
    throw new Error('useSnackbar must be used within a SnackbarProvider');
  }
  return context;
};
