import { useState, useEffect, forwardRef, useImperativeHandle, useRef } from 'react';
import { useAudio } from '@/contexts/AudioContext';
import { useUser } from '@/contexts/UserContext';
import { useTasks } from '@/contexts/TasksContext';
import { TAB_MENU_HEIGHT } from '@/constants/ui';
import { TASKS } from '@/constants/tasks';
import CookieRewardIcon from '@/assets/icons/cookie_reward.svg?react';

// Награда за добавление в историю
const STORY_REWARD = TASKS.find((t) => t.id === 'add_to_story')?.reward ?? 3;

interface FortuneTextProps {
  className?: string;
}

export interface FortuneTextRef {
  show: (text: string) => void;
  hide: () => void;
  getLastText: () => string;
}

export const FortuneText = forwardRef<FortuneTextRef, FortuneTextProps>(
  ({ className = '' }, ref) => {
    const [text, setText] = useState('');
    const [displayedText, setDisplayedText] = useState('');
    const [isVisible, setIsVisible] = useState(false);
    const [showAddToStorySection, setShowAddToStorySection] = useState(false);
    const lastTextRef = useRef<string>('');
    const { playTextTyping } = useAudio();
    const { userData } = useUser();
    const { executeTask, tasksStatus } = useTasks();

    // Проверяем, можно ли получить награду за ежедневное задание
    const canGetReward = tasksStatus['add_to_story']?.canComplete ?? true;

    const handleAddToStory = async () => {
      await executeTask('add_to_story');
    };

    useImperativeHandle(ref, () => ({
      show: (fortuneText: string) => {
        lastTextRef.current = fortuneText;
        setText(fortuneText);
        setIsVisible(true);
        setDisplayedText('');
        setShowAddToStorySection(false);
      },
      hide: () => {
        setIsVisible(false);
        setText('');
        setDisplayedText('');
        setShowAddToStorySection(false);
      },
      getLastText: () => {
        return lastTextRef.current;
      },
    }));

    // Эффект печатной машинки
    useEffect(() => {
      if (!isVisible || !text) return;

      // Флаг для предотвращения обновления state после unmount
      let isCancelled = false;

      // Запускаем звук печатания
      playTextTyping();

      const chars = text.split('');
      const totalTime = 3000; // 3 секунды на весь текст
      const timePerChar = totalTime / chars.length;

      let currentIndex = 0;
      const interval = setInterval(() => {
        if (isCancelled) {
          clearInterval(interval);
          return;
        }

        if (currentIndex <= chars.length) {
          setDisplayedText(chars.slice(0, currentIndex).join(''));
          currentIndex++;
        } else {
          clearInterval(interval);
          // Показываем кнопку после завершения анимации печати
          if (!isCancelled) {
            setShowAddToStorySection(true);
          }
        }
      }, timePerChar);

      return () => {
        isCancelled = true;
        clearInterval(interval);
      };
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [text, isVisible]);

    if (!isVisible) return null;

    return (
      <>
        <h1
          className={`font-nickname fixed top-[40%] left-1/2 z-1 w-[55vw] -translate-x-1/2 -translate-y-1/2 text-center text-[5vw] leading-[100%] tracking-[-0.5px] text-[#49382E] transition-all duration-[400ms] ease-in-out ${className}`}
        >
          {displayedText}
        </h1>
        <div
          className="fixed left-1/2 z-2 mb-[7vh] flex -translate-x-1/2 flex-col items-center gap-[20px] transition-opacity duration-300"
          style={{
            bottom: `${TAB_MENU_HEIGHT}px`,
            opacity: showAddToStorySection ? 1 : 0,
            pointerEvents: showAddToStorySection ? 'auto' : 'none',
          }}
        >
          {userData?.photoUrl && (
            <div className="relative h-[100px] w-[100px]">
              {/* Награда показывается только если таск ещё не выполнен сегодня */}
              {canGetReward && (
                <>
                  <CookieRewardIcon className="absolute right-[-35px] bottom-[-35px]" />
                  <div className="font-nickname font-regular text-outline-2-brown absolute right-[10px] bottom-[8px] text-[20px] text-white">
                    +{STORY_REWARD}
                  </div>
                </>
              )}
              <img
                src={userData.photoUrl}
                alt="User avatar"
                className="h-full w-full rounded-full object-cover"
              />
            </div>
          )}
          <button
            className="bg-secondary font-eurostile text-primary flex items-center justify-center rounded-[40px] px-[20px] py-[12px] text-[4.25vw] font-medium transition-transform active:scale-[0.98]"
            onClick={handleAddToStory}
          >
            <span className="translate-y-[2px]">Добавить в историю</span>
          </button>
        </div>
      </>
    );
  }
);

FortuneText.displayName = 'FortuneText';
