import React, { createContext, useContext, useState, useCallback, useEffect, useRef } from 'react';
import { useLoading } from './LoadingContext';
import { api } from '@/services/api';
import type { UserData, OpenCookieResponse } from '@/types/api';

interface UserContextValue {
  userData: UserData | null;
  isLoading: boolean;
  refreshUserData: () => Promise<void>;
  openCookie: () => Promise<OpenCookieResponse | null>;
}

interface UserProviderProps {
  children: React.ReactNode;
}

const UserContext = createContext<UserContextValue | undefined>(undefined);

export const UserProvider: React.FC<UserProviderProps> = ({ children }) => {
  const { setResourceLoaded } = useLoading();
  const [userData, setUserData] = useState<UserData | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const hasInitializedRef = useRef(false);

  const refreshUserData = useCallback(async () => {
    try {
      setIsLoading(true);
      const data = await api.processDailyLogin();
      setUserData(data);
      setResourceLoaded('userData');
    } catch (err) {
      console.error('Failed to refresh user data:', err);
      // Даже при ошибке помечаем как загруженное, чтобы не блокировать экран загрузки
      setResourceLoaded('userData');
    } finally {
      setIsLoading(false);
    }
  }, [setResourceLoaded]);

  // Загружаем userData при монтировании
  useEffect(() => {
    if (!hasInitializedRef.current) {
      hasInitializedRef.current = true;
      refreshUserData();
    }
  }, [refreshUserData]);

  const openCookie = useCallback(async (): Promise<OpenCookieResponse | null> => {
    try {
      const response = await api.openCookie();
      // Обновляем данные пользователя
      setUserData(response.user);
      return response;
    } catch (err) {
      console.error('Failed to open cookie:', err);
      throw err;
    }
  }, []);

  const value: UserContextValue = {
    userData,
    isLoading,
    refreshUserData,
    openCookie,
  };

  return <UserContext.Provider value={value}>{children}</UserContext.Provider>;
};

export const useUser = (): UserContextValue => {
  const context = useContext(UserContext);
  if (!context) {
    throw new Error('useUser must be used within UserProvider');
  }
  return context;
};
