import React, { createContext, useContext, useState, useCallback, useEffect, useRef } from 'react';
import { useLoading } from './LoadingContext';
import { api } from '@/services/api';
import type { Fortune } from '@/types/api';

interface FortuneContextValue {
  lastFortune: Fortune | null;
  currentFortune: Fortune | null;
  isLoading: boolean;
  loadLastFortune: () => Promise<void>;
  setCurrentFortune: (fortune: Fortune | null) => void;
  setLastFortune: (fortune: Fortune | null) => void;
}

interface FortuneProviderProps {
  children: React.ReactNode;
}

const FortuneContext = createContext<FortuneContextValue | undefined>(undefined);

export const FortuneProvider: React.FC<FortuneProviderProps> = ({ children }) => {
  const { setResourceLoaded } = useLoading();
  const [lastFortune, setLastFortune] = useState<Fortune | null>(null);
  const [currentFortune, setCurrentFortune] = useState<Fortune | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const hasInitializedRef = useRef(false);

  const loadLastFortune = useCallback(async () => {
    try {
      setIsLoading(true);
      const fortune = await api.getLastFortune();
      setLastFortune(fortune);
      setResourceLoaded('lastFortune');
    } catch (err) {
      console.warn('No last fortune found:', err);
      setLastFortune(null);
      setResourceLoaded('lastFortune');
    } finally {
      setIsLoading(false);
    }
  }, [setResourceLoaded]);

  // Загружаем lastFortune при монтировании
  useEffect(() => {
    if (!hasInitializedRef.current) {
      hasInitializedRef.current = true;
      loadLastFortune();
    }
  }, [loadLastFortune]);

  const value: FortuneContextValue = {
    lastFortune,
    currentFortune,
    isLoading,
    loadLastFortune,
    setCurrentFortune,
    setLastFortune,
  };

  return <FortuneContext.Provider value={value}>{children}</FortuneContext.Provider>;
};

export const useFortune = (): FortuneContextValue => {
  const context = useContext(FortuneContext);
  if (!context) {
    throw new Error('useFortune must be used within FortuneProvider');
  }
  return context;
};
