import React, { createContext, useContext, useState, useCallback } from 'react';
import { TabId } from '@/types/navigation';
import { TAB_ANIMATION_DURATION } from '@/constants/animations';

interface NavigationContextType {
  activeTab: TabId;
  prevTab: TabId;
  direction: 'left' | 'right';
  isTabAnimating: boolean;
  navigateToTab: (tabId: TabId) => void;
}

const NavigationContext = createContext<NavigationContextType | undefined>(undefined);

export const NavigationProvider: React.FC<{
  children: React.ReactNode;
}> = ({ children }) => {
  const [activeTab, setActiveTab] = useState<TabId>(TabId.MAIN);
  const [prevTab, setPrevTab] = useState<TabId>(TabId.MAIN);
  const [direction, setDirection] = useState<'left' | 'right'>('right');
  const [isTabAnimating, setIsTabAnimating] = useState<boolean>(false);

  const navigateToTab = useCallback((newTab: TabId) => {
    if (newTab === activeTab) return;

    // Определяем направление на основе индексов табов
    let newDirection: 'left' | 'right' = 'right';

    // Специальная логика для SKINS панели - всегда справа
    if (newTab === TabId.SKINS) {
      newDirection = 'right';
    } else if (activeTab === TabId.SKINS) {
      newDirection = 'left';
    } else {
      const tabs = [TabId.TASKS, TabId.MAIN, TabId.LEADERBOARD];
      const currentIndex = tabs.indexOf(activeTab);
      const newIndex = tabs.indexOf(newTab);
      if (currentIndex !== -1 && newIndex !== -1) {
        newDirection = newIndex > currentIndex ? 'right' : 'left';
      }
    }

    setDirection(newDirection);
    setPrevTab(activeTab);
    setActiveTab(newTab);
    setIsTabAnimating(true);

    // Сбрасываем флаг анимации после её завершения
    setTimeout(() => {
      setIsTabAnimating(false);
    }, TAB_ANIMATION_DURATION);
  }, [activeTab]);

  const value: NavigationContextType = {
    activeTab,
    prevTab,
    direction,
    isTabAnimating,
    navigateToTab,
  };

  return <NavigationContext.Provider value={value}>{children}</NavigationContext.Provider>;
};

export const useNavigation = (): NavigationContextType => {
  const context = useContext(NavigationContext);
  if (!context) {
    throw new Error('useNavigation must be used within NavigationProvider');
  }
  return context;
};
