import { createContext, useContext, useRef, useCallback, type ReactNode } from 'react';
import { api } from '@/services/api';
import type { MetricEventType } from '@/types/api';

// Генерация UUID v4
function generateUUID(): string {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

interface MetricsContextType {
  trackAppOpen: () => Promise<void>;
  trackCookieView: (textId: string) => Promise<void>;
  trackCookieShare: (textId: string) => Promise<void>;
  trackOpenNextCookie: (fromTextId: string | null) => Promise<void>;
  getSessionId: () => string;
}

const MetricsContext = createContext<MetricsContextType | null>(null);

interface MetricsProviderProps {
  children: ReactNode;
}

export function MetricsProvider({ children }: MetricsProviderProps) {
  // Генерируем sessionId один раз при создании провайдера
  const sessionIdRef = useRef<string>(generateUUID());

  const getSessionId = useCallback(() => {
    return sessionIdRef.current;
  }, []);

  const trackEvent = useCallback(
    async (eventType: MetricEventType, textId?: string, fromTextId?: string) => {
      try {
        await api.trackEvent({
          eventType,
          sessionId: sessionIdRef.current,
          textId,
          fromTextId,
        });
      } catch (error) {
        // Не блокируем UI при ошибках трекинга
        console.error('Failed to track event:', eventType, error);
      }
    },
    []
  );

  const trackAppOpen = useCallback(async () => {
    await trackEvent('app_open');
  }, [trackEvent]);

  const trackCookieView = useCallback(
    async (textId: string) => {
      await trackEvent('cookie_view', textId);
    },
    [trackEvent]
  );

  const trackCookieShare = useCallback(
    async (textId: string) => {
      await trackEvent('cookie_share', textId);
    },
    [trackEvent]
  );

  const trackOpenNextCookie = useCallback(
    async (fromTextId: string | null) => {
      await trackEvent('open_next_cookie', undefined, fromTextId || undefined);
    },
    [trackEvent]
  );

  return (
    <MetricsContext.Provider
      value={{
        trackAppOpen,
        trackCookieView,
        trackCookieShare,
        trackOpenNextCookie,
        getSessionId,
      }}
    >
      {children}
    </MetricsContext.Provider>
  );
}

export function useMetrics(): MetricsContextType {
  const context = useContext(MetricsContext);
  if (!context) {
    throw new Error('useMetrics must be used within a MetricsProvider');
  }
  return context;
}
