import React, { createContext, useContext, useState, useCallback, useEffect, useRef } from 'react';
import { api } from '@/services/api';
import { vkTasks } from '@/services/vkTasks';
import { useUser } from './UserContext';
import { useFortune } from './FortuneContext';
import { useSnackbar } from './SnackbarContext';
import { useSkins } from './SkinsContext';
import { useMetrics } from './MetricsContext';
import { useGlobalSpinner } from './GlobalSpinnerContext';
import type { TaskStatus, Fortune } from '@/types/api';
import type { CookieSkin } from '@/components/FloatingCookie';
import SnackbarCookieIcon from '@/assets/icons/snackbar_cookie.svg?react';

type TaskId =
  | 'subscribe_group'
  | 'allow_messages'
  | 'allow_notifications'
  | 'add_to_homescreen'
  | 'add_to_story';

interface TasksContextValue {
  tasksStatus: Record<string, TaskStatus>;
  isLoading: boolean;
  executeTask: (taskId: TaskId) => Promise<boolean>;
  refreshTasksStatus: () => Promise<void>;
}

const TasksContext = createContext<TasksContextValue | undefined>(undefined);

export const TasksProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { refreshUserData } = useUser();
  const { lastFortune } = useFortune();
  const { showSnackbar } = useSnackbar();
  const { currentSkin } = useSkins();
  const { trackCookieShare } = useMetrics();
  const { showSpinner, hideSpinner } = useGlobalSpinner();
  const [tasksStatus, setTasksStatus] = useState<Record<string, TaskStatus>>({});
  const [isLoading, setIsLoading] = useState(false);
  const hasInitializedRef = useRef(false);

  const refreshTasksStatus = useCallback(async () => {
    try {
      const response = await api.getTasksStatus();
      setTasksStatus(response.tasks);
    } catch (error) {
      console.error('Failed to load tasks status:', error);
    }
  }, []);

  useEffect(() => {
    if (!hasInitializedRef.current) {
      hasInitializedRef.current = true;
      refreshTasksStatus();
    }
  }, [refreshTasksStatus]);

  const executeVkTask = async (
    taskId: TaskId,
    fortune: Fortune | null,
    skin: CookieSkin
  ): Promise<boolean> => {
    switch (taskId) {
      case 'subscribe_group':
        return vkTasks.subscribeToGroup();
      case 'allow_messages':
        return vkTasks.allowMessages();
      case 'allow_notifications':
        return vkTasks.allowNotifications();
      case 'add_to_homescreen':
        return vkTasks.addToHomeScreen();
      case 'add_to_story':
        if (!fortune) {
          showSnackbar({
            title: 'Нет предсказания',
            description: 'Сначала откройте печенье с предсказанием',
            duration: 3000,
          });
          return false;
        }
        const shareSuccess = await vkTasks.shareToStory(fortune, skin);
        if (shareSuccess) {
          // Трекаем событие cookie_share после успешной публикации в сторис
          trackCookieShare(fortune._id);
        }
        return shareSuccess;
      default:
        return false;
    }
  };

  const executeTask = useCallback(
    async (taskId: TaskId): Promise<boolean> => {
      setIsLoading(true);
      showSpinner();
      try {
        // Execute VK Bridge action first
        const vkSuccess = await executeVkTask(taskId, lastFortune, currentSkin);

        if (!vkSuccess) {
          return false;
        }

        // If VK action succeeded, complete the task on backend
        const response = await api.completeTask(taskId);

        if (response.success) {
          // Refresh user data to update balance
          await refreshUserData();
          // Refresh tasks status
          await refreshTasksStatus();

          showSnackbar({
            icon: <SnackbarCookieIcon />,
            title: 'Задание выполнено!',
            description: `+${response.reward} печеньки`,
            duration: 3000,
          });
          return true;
        } else if (response.alreadyCompleted) {
          showSnackbar({
            title: 'Задание уже выполнено',
            description: 'Вы уже получили награду за это задание',
            duration: 3000,
          });
          return false;
        }

        return false;
      } catch (error) {
        console.error('Failed to execute task:', error);
        showSnackbar({
          title: 'Ошибка',
          description: 'Не удалось выполнить задание',
          duration: 3000,
        });
        return false;
      } finally {
        setIsLoading(false);
        hideSpinner();
      }
    },
    [lastFortune, currentSkin, refreshUserData, refreshTasksStatus, showSnackbar]
  );

  const value: TasksContextValue = {
    tasksStatus,
    isLoading,
    executeTask,
    refreshTasksStatus,
  };

  return <TasksContext.Provider value={value}>{children}</TasksContext.Provider>;
};

export const useTasks = (): TasksContextValue => {
  const context = useContext(TasksContext);
  if (!context) {
    throw new Error('useTasks must be used within TasksProvider');
  }
  return context;
};
