import React from 'react';
import MuteIcon from '@/assets/icons/mute.svg?react';
import SoundIcon from '@/assets/icons/sound.svg?react';
import { SPACING, TAB_MENU_HEIGHT, TAP_HINT_HEIGHT } from '@/constants/ui';
import { useAudio } from '@/contexts/AudioContext';

interface SoundToggleButtonProps {
  style?: React.CSSProperties;
  isHintHidden?: boolean;
}

export const SoundToggleButton: React.FC<SoundToggleButtonProps> = ({
  style,
  isHintHidden = false,
}) => {
  const { isMuted, toggleMute } = useAudio();

  // Если hint скрыт, позиция без TAP_HINT_HEIGHT и одного SPACING
  const bottomPosition = isHintHidden
    ? TAB_MENU_HEIGHT + SPACING
    : TAB_MENU_HEIGHT + TAP_HINT_HEIGHT + 2 * SPACING;

  return (
    <button
      className="bg-primary fixed z-2 flex h-[50px] w-[50px] cursor-pointer items-center justify-center rounded-[15px] opacity-[0.6] transition-opacity hover:opacity-[0.8]"
      style={{
        left: `${SPACING}px`,
        bottom: `${bottomPosition}px`,
        transition: 'transform 400ms ease-in-out',
        ...style,
      }}
      onClick={toggleMute}
    >
      {isMuted ? <SoundIcon /> : <MuteIcon />}
    </button>
  );
};
