import { useEffect, useRef, useImperativeHandle, forwardRef, memo } from 'react';
import lottie from 'lottie-web';
import { COOKIE_TIMING } from '@/constants/cookieTiming';

export type CookieSkin = 'standart2' | 'fuckman' | 'glasses' | 'lips' | 'rose' | 'tie';

interface FloatingCookieProps {
  skin?: CookieSkin;
  className?: string;
  onAnimationLoaded?: () => void;
  onClick?: () => void;
}

export interface FloatingCookieRef {
  playEntry: () => Promise<void>;
  playCycle: () => void;
  playClick: () => void;
  playExplosive: () => Promise<void>;
  show: () => void;
  hide: () => void;
}

const FloatingCookieComponent = forwardRef<FloatingCookieRef, FloatingCookieProps>(
  ({ skin = 'standart2', className = '', onAnimationLoaded, onClick }, ref) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const animationRef = useRef<ReturnType<typeof lottie.loadAnimation> | null>(null);
    const onAnimationLoadedRef = useRef(onAnimationLoaded);
    const clickTimeoutRef = useRef<NodeJS.Timeout | null>(null);

    // Обновляем ref при изменении коллбэка
    useEffect(() => {
      onAnimationLoadedRef.current = onAnimationLoaded;
    }, [onAnimationLoaded]);

    // Expose methods to parent component
    useImperativeHandle(
      ref,
      () => ({
        playEntry: async () => {
          if (!animationRef.current) return;

          return new Promise<void>((resolve) => {
            const animation = animationRef.current!;

            // Останавливаем текущий луп
            animation.loop = false;
            animation.stop();

            // Проигрываем entry сегмент
            animation.playSegments(COOKIE_TIMING.entry, true);

            // Слушаем завершение entry анимации
            const onComplete = () => {
              animation.removeEventListener('complete', onComplete);

              // Переключаемся на cycle луп
              animation.loop = true;
              animation.playSegments(COOKIE_TIMING.cycle, true);

              resolve();
            };

            animation.addEventListener('complete', onComplete);
          });
        },
        playCycle: () => {
          if (!animationRef.current) return;

          const animation = animationRef.current;
          animation.loop = true;
          animation.playSegments(COOKIE_TIMING.cycle, true);
        },
        playClick: () => {
          if (!animationRef.current) return;

          const animation = animationRef.current;
          animation.loop = false;
          animation.playSegments(COOKIE_TIMING.click, true);

          // Очищаем предыдущий таймаут возврата к cycle
          if (clickTimeoutRef.current) {
            clearTimeout(clickTimeoutRef.current);
          }

          // После завершения клика возвращаемся к cycle через setTimeout
          const duration =
            ((COOKIE_TIMING.click[1] - COOKIE_TIMING.click[0]) / COOKIE_TIMING.framerate) * 1000 -
            25;

          clickTimeoutRef.current = setTimeout(() => {
            if (animationRef.current) {
              animationRef.current.loop = true;
              animationRef.current.playSegments(COOKIE_TIMING.cycle, true);
            }
          }, duration);
        },
        playExplosive: async () => {
          if (!animationRef.current) return;

          const animation = animationRef.current;

          // Очищаем таймаут возврата к cycle от предыдущих кликов
          if (clickTimeoutRef.current) {
            clearTimeout(clickTimeoutRef.current);
            clickTimeoutRef.current = null;
          }

          // Останавливаем анимацию и отключаем loop
          animation.loop = false;

          // Проигрываем explosive сегмент один раз
          animation.playSegments(COOKIE_TIMING.explosive, true);

          // Вычисляем длительность анимации в миллисекундах
          const duration =
            ((COOKIE_TIMING.explosive[1] - COOKIE_TIMING.explosive[0]) / COOKIE_TIMING.framerate) *
              1000 -
            25;

          // Ждем окончания анимации
          await new Promise<void>((resolve) => {
            setTimeout(() => {
              // После взрыва анимация останавливается на последнем кадре
              // НЕ возвращаемся к cycle
              resolve();
            }, duration);
          });
        },
        show: () => {
          if (containerRef.current) {
            containerRef.current.style.display = '';
            containerRef.current.style.transition = 'opacity 300ms ease-in-out';
            requestAnimationFrame(() => {
              if (containerRef.current) {
                containerRef.current.style.opacity = '1';
              }
            });
          }
        },
        hide: () => {
          if (containerRef.current) {
            containerRef.current.style.display = 'none';
            containerRef.current.style.opacity = '0';
          }
        },
      }),
      []
    );

    useEffect(() => {
      let isMounted = true;
      let loadingCanceled = false;

      const loadAnimation = async () => {
        if (!containerRef.current) return;

        // Уничтожаем предыдущую анимацию, если она есть
        if (animationRef.current) {
          animationRef.current.destroy();
          animationRef.current = null;
        }

        try {
          // Динамически импортируем JSON файл анимации
          const animationData = await import(`@/assets/lottie/cookie_${skin}_optimized.json`);

          // Проверяем, что загрузка не была отменена и компонент всё ещё примонтирован
          if (loadingCanceled || !isMounted || !containerRef.current) return;

          // Загружаем анимацию, но НЕ автоплей
          animationRef.current = lottie.loadAnimation({
            container: containerRef.current,
            renderer: 'svg',
            loop: false,
            autoplay: false,
            animationData: animationData.default || animationData,
          });

          // Уведомляем о загрузке анимации
          if (onAnimationLoadedRef.current) {
            onAnimationLoadedRef.current();
          }
        } catch (error) {
          console.error(`Failed to load cookie animation for skin: ${skin}`, error);
        }
      };

      loadAnimation();

      // Очистка при размонтировании или смене скина
      return () => {
        isMounted = false;
        loadingCanceled = true; // Отменяем обработку результатов загрузки
        if (clickTimeoutRef.current) {
          clearTimeout(clickTimeoutRef.current);
          clickTimeoutRef.current = null;
        }
        if (animationRef.current) {
          animationRef.current.destroy();
          animationRef.current = null;
        }
      };
    }, [skin]);

    return (
      <div
        id="lottie-cookie"
        ref={containerRef}
        className={`floating-cookie ${className} cursor-pointer`}
        style={{ display: 'none', opacity: 0 }}
        onClick={onClick}
      />
    );
  }
);

FloatingCookieComponent.displayName = 'FloatingCookie';

// Оптимизация: мемоизируем компонент, чтобы избежать лишних рендеров
const FloatingCookie = memo(FloatingCookieComponent);

export { FloatingCookie };
export default FloatingCookie;
