import React, { useEffect, useCallback } from 'react';
import { TabId, type TabItem } from '@/types/navigation';
import { Layout } from '@/components/Layout';
import { AppProviders } from '@/components/AppProviders';
import { useNavigation } from '@/contexts/NavigationContext';
import { useAnimations } from '@/contexts/AnimationsContext';
import { useAudio } from '@/contexts/AudioContext';
import { useLoading } from '@/contexts/LoadingContext';
import { useSkins } from '@/contexts/SkinsContext';
import TasksIcon from '@/assets/icons/tasks.svg?react';
import MainIcon from '@/assets/icons/main.svg?react';
import LeaderboardIcon from '@/assets/icons/leaderboard.svg?react';
import { SkinsPanel } from '@/components/panels/SkinsPanel';
import { MainPanel } from '@/components/panels/MainPanel';
import { TasksPanel } from '@/components/panels/TasksPanel';
import { LeaderboardPanel } from '@/components/panels/LeaderboardPanel';

const tabs: TabItem[] = [
  { id: TabId.TASKS, label: 'Задания', icon: <TasksIcon /> },
  { id: TabId.MAIN, label: 'Главная', icon: <MainIcon /> },
  { id: TabId.LEADERBOARD, label: 'Топ', icon: <LeaderboardIcon /> },
];

const AppContent: React.FC = () => {
  const { activeTab, prevTab, direction, isTabAnimating, navigateToTab } = useNavigation();
  const { cookieRef } = useAnimations();
  const { playBackgroundCookie, playBackgroundNoCookie } = useAudio();
  const { isStarted } = useLoading();
  const { currentSkin, selectSkin } = useSkins();

  // Управление фоновой музыкой в зависимости от активного таба
  useEffect(() => {
    if (!isStarted) return; // Не запускаем музыку до нажатия "Начать"

    if (activeTab === TabId.MAIN) {
      playBackgroundCookie();
    } else {
      playBackgroundNoCookie();
    }
  }, [activeTab, isStarted, playBackgroundCookie, playBackgroundNoCookie]);

  // Управление видимостью печеньки в зависимости от активного таба
  useEffect(() => {
    if (!isStarted || !cookieRef.current) return;

    if (activeTab === TabId.MAIN) {
      // Показываем печеньку на MainPanel
      cookieRef.current.show();
    } else {
      // Скрываем печеньку на других панелях
      cookieRef.current.hide();
    }
  }, [activeTab, isStarted, cookieRef]);

  const getPanelComponent = useCallback(
    (tabId: TabId) => {
      switch (tabId) {
        case TabId.TASKS:
          return <TasksPanel id={TabId.TASKS} />;
        case TabId.MAIN:
          return <MainPanel id={TabId.MAIN} onOpenSkins={() => navigateToTab(TabId.SKINS)} />;
        case TabId.LEADERBOARD:
          return <LeaderboardPanel id={TabId.LEADERBOARD} />;
        case TabId.SKINS:
          return (
            <SkinsPanel
              id={TabId.SKINS}
              currentSkin={currentSkin}
              onSkinSelect={(skin, onLoaded) => {
                selectSkin(skin, () => {
                  onLoaded();
                  // Возвращаемся на главный экран после загрузки анимации
                  navigateToTab(TabId.MAIN);
                });
              }}
              onClose={() => navigateToTab(TabId.MAIN)}
            />
          );
        default:
          return <MainPanel id={TabId.MAIN} onOpenSkins={() => navigateToTab(TabId.SKINS)} />;
      }
    },
    [currentSkin, selectSkin, navigateToTab]
  );

  const renderPanel = () => {
    return (
      <div className="relative h-full w-full">
        {/* Старый таб - исчезает */}
        {isTabAnimating && prevTab !== activeTab && (
          <div
            key={`${prevTab}-out`}
            className={`panel-container panel-exit absolute inset-0 ${
              direction === 'right' ? 'slide-out-left' : 'slide-out-right'
            }`}
          >
            {getPanelComponent(prevTab)}
          </div>
        )}

        {/* Новый таб - появляется */}
        <div
          key={activeTab}
          className={`panel-container ${
            isTabAnimating ? (direction === 'right' ? 'slide-in-right' : 'slide-in-left') : ''
          }`}
        >
          {getPanelComponent(activeTab)}
        </div>
      </div>
    );
  };

  return (
    <Layout
      activeTab={activeTab}
      onTabChange={navigateToTab}
      tabs={tabs}
      currentSkin={currentSkin}
    >
      {renderPanel()}
    </Layout>
  );
};

const App: React.FC = () => {
  return (
    <AppProviders>
      <AppContent />
    </AppProviders>
  );
};

export default App;
