import React, { useState, useEffect } from 'react';
import { TaskItem } from '../TaskItem';
import { TASKS } from '@/constants/tasks';
import { SPACING, TAB_MENU_HEIGHT } from '@/constants/ui';
import { useModal } from '@/contexts/ModalContext';
import { useTasks } from '@/contexts/TasksContext';
import { isVKMethodSupported, type VKTaskMethod } from '@/services/vkTasks';
import BigCookie from '@/assets/icons/big_cookie.svg?react';

/** Маппинг task ID к методам VK Bridge */
const TASK_VK_METHOD_MAP: Record<string, VKTaskMethod> = {
  subscribe_group: 'VKWebAppJoinGroup',
  allow_messages: 'VKWebAppAllowMessagesFromGroup',
  allow_notifications: 'VKWebAppAllowNotifications',
  add_to_homescreen: 'VKWebAppAddToHomeScreen',
  add_to_story: 'VKWebAppShowStoryBox',
};

interface TasksPanelProps {
  id: string;
}

export const TasksPanel: React.FC<TasksPanelProps> = () => {
  const { showModal } = useModal();
  const { tasksStatus, executeTask } = useTasks();
  const [supportedTasks, setSupportedTasks] = useState<Set<string>>(new Set());

  // Проверяем поддержку методов VK Bridge при монтировании
  useEffect(() => {
    const checkSupport = async () => {
      const supported = new Set<string>();

      for (const task of TASKS) {
        const vkMethod = TASK_VK_METHOD_MAP[task.id];
        if (vkMethod) {
          const isSupported = await isVKMethodSupported(vkMethod);
          if (isSupported) {
            supported.add(task.id);
          }
        }
      }

      setSupportedTasks(supported);
    };

    checkSupport();
  }, []);

  // Фильтруем таски по поддержке на текущей платформе
  const filteredTasks = TASKS.filter((task) => supportedTasks.has(task.id));

  const dailyTasks = filteredTasks.filter((task) => task.daily);
  const regularTasks = filteredTasks.filter((task) => !task.daily);

  const isTaskCompleted = (taskId: string): boolean => {
    const status = tasksStatus[taskId];
    return status?.completed && !status?.canComplete;
  };

  const handleTaskClick = (taskId: string) => {
    const task = TASKS.find((t) => t.id === taskId);
    if (!task || !task.modal) return;

    showModal({
      icon: task.modal.icon,
      title: task.title,
      description: task.modal.description,
      buttonText: task.modal.buttonText,
      reward: task.reward,
      onButtonClick: () => executeTask(taskId as Parameters<typeof executeTask>[0]),
    });
  };

  return (
    <div
      className="relative h-screen overflow-y-auto"
      style={{
        paddingBottom: `${TAB_MENU_HEIGHT + SPACING}px`,
        paddingLeft: `${SPACING}px`,
        paddingRight: `${SPACING}px`,
      }}
    >
      <div className="flex flex-col">
        <BigCookie className="mx-auto mb-[-75px]" />
        <div className="font-nickname text-outline-3 text-center text-[32px] text-white">
          Выполняйте задания
          <br />
          <div className="text-secondary">и получайте печеньки</div>
        </div>
        <div className="font-eurostile text-outline-3 my-[15px] text-center text-[24px] font-bold text-white">
          Список заданий:
        </div>
        <div className="flex flex-col gap-[10px]">
          {regularTasks.map((task) => (
            <TaskItem
              key={task.id}
              task={{
                ...task,
                onClick: () => handleTaskClick(task.id),
              }}
              icon={task.icon}
              completed={isTaskCompleted(task.id)}
            />
          ))}
        </div>
      </div>
      <div className="font-eurostile text-outline-3 my-[15px] text-center text-[24px] font-bold text-white">
        Ежедневные задания:
      </div>
      <div className="flex flex-col gap-[10px]">
        {dailyTasks.map((task) => (
          <TaskItem
            key={task.id}
            task={{
              ...task,
              onClick: () => handleTaskClick(task.id),
            }}
            icon={task.icon}
            completed={isTaskCompleted(task.id)}
          />
        ))}
      </div>
    </div>
  );
};
